INSERT INTO "StudyMaterial" ("id", "userId", "fileName", "originalFileName", "filePath", "googleDriveFileId", "mimeType", "fileSize", "totalPages", "sourceType", "sourcePath", "fileHash", "organizationStatus", "detectedSubjectName", "detectedStructure", "processingStatus", "processingError", "subjectId", "createdAt", "updatedAt", "materialRole", "supportForTopicId", "provider") VALUES ('cmpeai6w300g5l704987lgm5g', 'cmp8od0wz0000iybklaotfqbs', 'direito do trabalho 6.pdf', 'direito do trabalho 6.pdf', NULL, NULL, 'application/pdf', 2154690, 170, 'CLOUD_UPLOAD', 'cmp8od0wz0000iybklaotfqbs/ee82f0ee-70cd-49a9-ab0b-f9db3653882f.pdf', NULL, 'ORGANIZED', 'Direito do Trabalho', '{"materialRole":"MIXED_MATERIAL","sourceStrategy":"TOC_BASED","tocDetected":true,"tocConfidence":1,"blocks":[{"type":"MAIN_BLOCK","title":"Remuneração e Salário — Conceitos, Art. 7º CF/88 e Terminologias + Salário — Denominações Impróprias","titleQuality":"GOOD","titleRationale":"O título é específico, abrangendo a introdução ao tema, os direitos constitucionais correlatos e as distinções iniciais de terminologia entre salário e remuneração, conforme o início do material.","description":"Estudo dos fundamentos de remuneração e salário, a relevância do Art. 7º da CF/88 e as distinções conceituais iniciais. | Análise das diversas denominações de salário no direito do trabalho e previden","sourceHeading":"1) Sistema Remuneratório","pageStart":3,"pageEnd":9,"estimatedStudyMinutes":60,"contentDensity":"VERY_HIGH","officialTopicId":"work_t7","officialTopicName":"Remuneração e salário. Equiparação salarial.","topicCode":"Tópico 07","pageTypes":["MAIN_THEORY","EXPLANATION"],"selectionJustification":"As páginas 3 e 4 compreendem a introdução do tema ''Remuneração e Salário'', o tratamento do assunto no Art. 7º da CF/88 e o início das ''Terminologias'', formando uma unidade pedagógica coerente para os conceitos básicos. A densidade do conteúdo justifica o tempo estimado.","isMechanicalCut":false,"isSummaryOnly":false,"isQuestionsOnly":false,"supportType":null,"supportGroupingRationale":null,"mergeRationale":"Backend auto-merged consecutive short blocks of the same topic to reach 45 min target.","isShortBlock":false,"shortBlockJustification":null},{"type":"MAIN_BLOCK","title":"Salário — Características Essenciais e Parcelas Adicionais (Insalubridade e Periculosidade)","titleQuality":"GOOD","titleRationale":"O título abrange as características gerais do salário e inicia a abordagem detalhada das parcelas adicionais, focando nos adicionais de insalubridade e periculosidade que são densos e foram explicitados na amostra de texto.","description":"Estudo das características fundamentais do salário e aprofundamento nos adicionais de insalubridade e periculosidade, suas bases de cálculo e condições de incidência.","sourceHeading":"1) Sistema Remuneratório","pageStart":10,"pageEnd":15,"estimatedStudyMinutes":60,"contentDensity":"VERY_HIGH","officialTopicId":"work_t7","officialTopicName":"Remuneração e salário. Equiparação salarial.","topicCode":"Tópico 07","pageTypes":["MAIN_THEORY","EXPLANATION"],"selectionJustification":"As páginas abordam as características do salário e detalham os adicionais de insalubridade e periculosidade. A complexidade e a quantidade de informações sobre esses dois adicionais justificam um bloco separado, mantendo a coerência temática com as ''Parcelas salariais'' do ''Sistema Remuneratório''.","isMechanicalCut":false,"isSummaryOnly":false,"isQuestionsOnly":false,"supportType":null,"supportGroupingRationale":null},{"type":"MAIN_BLOCK","title":"Salário — Outras Parcelas Adicionais (Noturno, Horas Extras, Gratificações, Comissões)","titleQuality":"GOOD","titleRationale":"Título que consolida a continuidade da discussão sobre as parcelas salariais, focando em outros adicionais comuns e formas de gratificação e comissão, seguindo uma progressão lógica após os adicionais de risco.","description":"Continuação do estudo das parcelas salariais, incluindo adicional noturno, horas extras, gratificações, comissões e outras verbas que compõem a remuneração do empregado.","sourceHeading":"1) Sistema Remuneratório","pageStart":16,"pageEnd":27,"estimatedStudyMinutes":60,"contentDensity":"HIGH","officialTopicId":"work_t7","officialTopicName":"Remuneração e salário. Equiparação salarial.","topicCode":"Tópico 07","pageTypes":["MAIN_THEORY","EXPLANATION"],"selectionJustification":"Este bloco assume a continuação do tópico ''Parcelas salariais'' do ''Sistema Remuneratório'', abordando outros adicionais e gratificações que não puderam ser detalhados no bloco anterior devido à densidade, seguindo uma progressão pedagógica do conteúdo.","isMechanicalCut":false,"isSummaryOnly":false,"isQuestionsOnly":false,"supportType":null,"supportGroupingRationale":null},{"type":"MAIN_BLOCK","title":"Remuneração e Salário — Diárias, Ajuda de Custo e Verbas de Natureza Não Salarial","titleQuality":"GOOD","titleRationale":"Este título conclui a unidade temática ''Sistema Remuneratório'', abordando os componentes finais da remuneração e a crucial distinção entre o que é salário e o que não é, preparando para o próximo tema do sumário.","description":"Estudo de diárias, ajuda de custo e aprofundamento na distinção entre parcelas de natureza salarial e não salarial, finalizando a discussão sobre o sistema remuneratório.","sourceHeading":"1) Sistema Remuneratório","pageStart":28,"pageEnd":39,"estimatedStudyMinutes":60,"contentDensity":"HIGH","officialTopicId":"work_t7","officialTopicName":"Remuneração e salário. Equiparação salarial.","topicCode":"Tópico 07","pageTypes":["MAIN_THEORY","EXPLANATION"],"selectionJustification":"Este bloco conclui a abrangente seção ''Sistema Remuneratório'', abordando os componentes restantes da remuneração e a diferenciação de verbas não salariais, formando a finalização lógica do tema antes da ''Equiparação Salarial'' no sumário.","isMechanicalCut":false,"isSummaryOnly":false,"isQuestionsOnly":false,"supportType":null,"supportGroupingRationale":null},{"type":"MAIN_BLOCK","title":"Equiparação Salarial — Requisitos, Efeitos e Jurisprudência","titleQuality":"GOOD","titleRationale":"O título é direto e específico, refletindo o tópico do sumário e indicando a profundidade do estudo ao mencionar requisitos, efeitos e jurisprudência, conforme esperado para um tema jurídico.","description":"Estudo aprofundado da equiparação salarial no Direito do Trabalho, incluindo os requisitos legais para sua concessão, seus efeitos jurídicos e a relevante jurisprudência do TST.","sourceHeading":"2) Equiparação Salarial","pageStart":40,"pageEnd":54,"estimatedStudyMinutes":60,"contentDensity":"HIGH","officialTopicId":"work_t7","officialTopicName":"Remuneração e salário. Equiparação salarial.","topicCode":"Tópico 07","pageTypes":["MAIN_THEORY","EXPLANATION"],"selectionJustification":"Este bloco é uma unidade temática autônoma dedicada à ''Equiparação Salarial'', conforme explicitado no sumário, e sua extensão de páginas permite o tratamento completo e aprofundado do assunto, alinhado ao tempo de estudo ideal.","isMechanicalCut":false,"isSummaryOnly":false,"isQuestionsOnly":false,"supportType":null,"supportGroupingRationale":null},{"type":"SUPPORT_BLOCK","title":"Questões Comentadas — Salário e Remuneração - TRT","titleQuality":"GOOD","titleRationale":"O título é claro e específico, indicando que o bloco contém questões resolvidas e comentadas sobre os temas abordados, conforme o sumário do material.","description":"Conjunto de questões de concursos anteriores sobre Salário e Remuneração, com gabarito e comentários detalhados para fixação do conteúdo.","sourceHeading":"3) Questões Comentadas - Salário e Remuneração - TRT","pageStart":55,"pageEnd":133,"estimatedStudyMinutes":0,"contentDensity":"MEDIUM","officialTopicId":"work_t7","officialTopicName":"Remuneração e salário. Equiparação salarial.","topicCode":"Tópico 07","pageTypes":["QUESTIONS","EXPLANATION"],"selectionJustification":"Esta seção é uma unidade de apoio dedicada exclusivamente a questões comentadas sobre os temas de salário e remuneração, conforme indicado explicitamente no sumário do material, e não deve ser misturada com teoria principal.","isMechanicalCut":false,"isSummaryOnly":false,"isQuestionsOnly":true,"supportType":"COMMENTED_QUESTIONS","supportGroupingRationale":"Agrupa todas as questões comentadas para permitir uma revisão focada e aprofundada dos tópicos de remuneração e equiparação salarial."},{"type":"SUPPORT_BLOCK","title":"Lista de Questões — Salário e Remuneração - TRT","titleQuality":"GOOD","titleRationale":"O título é direto e específico, descrevendo o conteúdo do bloco como uma lista de questões para prática, conforme a indicação do sumário do material.","description":"Lista de questões para a prática e autoavaliação dos conhecimentos sobre Salário e Remuneração, sem comentários, para simular condições de prova.","sourceHeading":"4) Lista de Questões - Salário e Remuneração - TRT","pageStart":134,"pageEnd":170,"estimatedStudyMinutes":0,"contentDensity":"LOW","officialTopicId":"work_t7","officialTopicName":"Remuneração e salário. Equiparação salarial.","topicCode":"Tópico 07","pageTypes":["QUESTIONS"],"selectionJustification":"Esta seção é uma unidade de apoio dedicada a uma lista de questões para prática e revisão, sem comentários, conforme explicitado no sumário, e ocupa as páginas finais do material.","isMechanicalCut":false,"isSummaryOnly":false,"isQuestionsOnly":true,"supportType":"QUESTIONS","supportGroupingRationale":"Agrupa uma lista de questões para que o estudante possa praticar e testar seus conhecimentos sobre os tópicos de remuneração e equiparação salarial de forma independente."}],"aiModelUsed":"gemini-2.5-flash"}', 'PENDING', NULL, 'cmp992nry0001l404o53vsbkj', '2026-05-20T16:42:19.875', '2026-05-20T16:48:10.172', 'MIXED_MATERIAL', NULL, 'OTHER') ON CONFLICT ("id") DO UPDATE SET "userId" = EXCLUDED."userId", "fileName" = EXCLUDED."fileName", "originalFileName" = EXCLUDED."orig