INSERT INTO "StudyMaterial" ("id", "userId", "fileName", "originalFileName", "filePath", "googleDriveFileId", "mimeType", "fileSize", "totalPages", "sourceType", "sourcePath", "fileHash", "organizationStatus", "detectedSubjectName", "detectedStructure", "processingStatus", "processingError", "subjectId", "createdAt", "updatedAt", "materialRole", "supportForTopicId", "provider") VALUES ('cmpeahzzq00g3l704wku7f2v1', 'cmp8od0wz0000iybklaotfqbs', 'processual do trabalho 6.pdf', 'processual do trabalho 6.pdf', NULL, NULL, 'application/pdf', 3366935, 145, 'CLOUD_UPLOAD', 'cmp8od0wz0000iybklaotfqbs/4e1758c6-2ef3-457c-a3ed-5d695520fb9c.pdf', NULL, 'ORGANIZED', 'Direito Processual do Trabalho', '{"materialRole":"MIXED_MATERIAL","sourceStrategy":"CONTENT_BASED","tocDetected":false,"tocConfidence":0,"blocks":[{"type":"MAIN_BLOCK","title":"Teoria Geral dos Recursos Trabalhistas — conceito, classificação, regras, efeitos e princípios","titleQuality":"GOOD","titleRationale":"O título é específico e abrange os principais subtópicos da teoria geral dos recursos, conforme a estrutura interna do material (conceito, classificação, regras específicas, efeitos e princípios recursais).","description":"Estudo do conceito, classificações, regras específicas do processo do trabalho, efeitos dos recursos e os princípios recursais que regem a matéria, com exemplos práticos e jurisprudência.","sourceHeading":"Conceito de Recursos","pageStart":3,"pageEnd":28,"estimatedStudyMinutes":60,"contentDensity":"HIGH","officialTopicId":"proc_work_t6","officialTopicName":"Recursos no processo do trabalho — teoria geral e recursos em espécie.","topicCode":"Tópico 06","pageTypes":["MAIN_THEORY","EXPLANATION","QUESTIONS"],"selectionJustification":"Agrupamento de seções relacionadas à fundamentação e bases dos recursos trabalhistas (''Conceito de Recursos'', ''Classificação dos Recursos'', ''Regras específicas dos recursos'', ''Efeitos dos Recursos'' e ''Princípios Recursais'') para formar uma unidade pedagógica coesa sobre a teoria geral dos recursos, conforme indicado pelo sumário interno do material e para atender à duração mínima do bloco teórico.","isMechanicalCut":false,"isSummaryOnly":false,"isQuestionsOnly":false,"supportType":null,"supportGroupingRationale":null},{"type":"SUPPORT_BLOCK","title":"Juízo de Admissibilidade dos Recursos Trabalhistas — pressupostos e juízo de mérito","titleQuality":"GOOD","titleRationale":"O título especifica o tema central do bloco, incluindo os dois sub-elementos principais (''Pressupostos de Admissibilidade'' e ''Juízo de mérito dos recursos'') que compõem a seção interna do material.","description":"Análise do juízo de admissibilidade recursal, abordando os pressupostos extrínsecos e intrínsecos de admissibilidade e o juízo de mérito dos recursos no processo do trabalho.","sourceHeading":"Juízo de Admissibilidade","pageStart":29,"pageEnd":58,"estimatedStudyMinutes":0,"contentDensity":"HIGH","officialTopicId":"proc_work_t6","officialTopicName":"Recursos no processo do trabalho — teoria geral e recursos em espécie.","topicCode":"Tópico 06","pageTypes":["MAIN_THEORY","EXPLANATION"],"selectionJustification":"Bloco formado a partir de uma seção temática distinta do sumário interno (''Juízo de Admissibilidade''), que trata de um aspecto fundamental da teoria recursal, incluindo seus pressupostos e mérito, respeitando o início e fim natural do assunto.","isMechanicalCut":false,"isSummaryOnly":false,"isQuestionsOnly":true,"supportType":"ANSWER_KEY","supportGroupingRationale":null},{"type":"SUPPORT_BLOCK","title":"Recurso Ordinário no Processo do Trabalho","titleQuality":"GOOD","titleRationale":"Título direto e específico para uma das principais espécies recursais, conforme o sumário interno do material.","description":"Estudo detalhado do Recurso Ordinário, sua natureza, cabimento, legitimidade e procedimento na Justiça do Trabalho.","sourceHeading":"Recurso Ordinário","pageStart":59,"pageEnd":68,"estimatedStudyMinutes":0,"contentDensit