INSERT INTO "StudyMaterial" ("id", "userId", "fileName", "originalFileName", "filePath", "googleDriveFileId", "mimeType", "fileSize", "totalPages", "sourceType", "sourcePath", "fileHash", "organizationStatus", "detectedSubjectName", "detectedStructure", "processingStatus", "processingError", "subjectId", "createdAt", "updatedAt", "materialRole", "supportForTopicId", "provider") VALUES ('cmpeagiaf00fvl704z7rdfhid', 'cmp8od0wz0000iybklaotfqbs', 'direito do trabalho 5.pdf', 'direito do trabalho 5.pdf', NULL, NULL, 'application/pdf', 2633448, 129, 'CLOUD_UPLOAD', 'cmp8od0wz0000iybklaotfqbs/c3c3d858-3f33-49d8-8672-be2b5b77f240.pdf', NULL, 'ORGANIZED', 'Direito do Trabalho', '{"materialRole":"MIXED_MATERIAL","sourceStrategy":"TOC_BASED","tocDetected":true,"tocConfidence":1,"blocks":[{"type":"MAIN_BLOCK","title":"Jornada de Trabalho — tempo à disposição, in itinere, prontidão e sobreaviso","titleQuality":"GOOD","titleRationale":"O título reflete os principais subtópicos abordados na seção 1 do sumário, que incluem a definição de jornada, tempo à disposição (com e sem consideração), tempo in itinere e os regimes de prontidão e sobreaviso. É específico e pedagógico.","description":"Estudo sobre o conceito de jornada de trabalho, o que é considerado tempo à disposição do empregador (incluindo variações após a reforma trabalhista), a extinção do tempo in itinere e as particularidades dos regimes de prontidão e sobreaviso.","sourceHeading":"1) Jornada de Trabalho","pageStart":3,"pageEnd":7,"estimatedStudyMinutes":30,"contentDensity":"MEDIUM","officialTopicId":"work_t6","officialTopicName":"Jornada de trabalho e descansos.","topicCode":"Tópico 06","pageTypes":["MAIN_THEORY","EXPLANATION"],"selectionJustification":"Esta seção do sumário agrupa a introdução à jornada de trabalho, definindo seus conceitos fundamentais e as diferentes formas de computo do tempo de trabalho, formando uma unidade temática coerente.","isMechanicalCut":false,"isSummaryOnly":false,"isQuestionsOnly":false,"supportType":null,"supportGroupingRationale":null},{"type":"MAIN_BLOCK","title":"Jornadas Especiais de Trabalho — turnos ininterruptos, trabalho intermitente e tempo parcial","titleQuality":"GOOD","titleRationale":"O título expande o tópico genérico ''Jornadas Especiais de Trabalho'' do sumário, detalhando as três principais modalidades (turnos ininterruptos de revezamento, trabalho intermitente e regime de tempo parcial) que são tratadas em profundidade no conteúdo das páginas indicadas.","description":"Análise das modalidades de jornada de trabalho que se diferenciam do padrão, com foco nos turnos ininterruptos de revezamento, no contrato de trabalho intermitente e no regime de tempo parcial, abordando suas regras e exceções.","sourceHeading":"2) Jornadas Especiais de Trabalho","pageStart":8,"pageEnd":13,"estimatedStudyMinutes":30,"contentDensity":"MEDIUM","officialTopicId":"work_t6","officialTopicName":"Jornada de trabalho e descansos.","topicCode":"Tópico 06","pageTypes":["MAIN_THEORY","EXPLANATION"],"selectionJustification":"O sumário claramente delimita este bloco para tratar das jornadas especiais de trabalho, que possuem regras próprias e merecem um estudo aprofundado e separado dos conceitos gerais de jornada.","isMechanicalCut":false,"isSummaryOnly":false,"isQuestionsOnly":false,"supportType":null,"supportGroupingRationale":null},{"type":"MAIN_BLOCK","title":"Trabalho Extraordinário e Compensação de Jornada — limites, adicionais e tipos de compensação","titleQuality":"GOOD","titleRationale":"O título especifica os aspectos cruciais do trabalho extraordinário e da compensação de jornada, como os limites legais, os adicionais de remuneração e as formas de compensação (acordo de prorrogação e banco de horas), conforme abordado no conteúdo.","description":"Estudo aprofundado sobre a jornada extraordinária (horas extras), incluindo seus limites diários, o percentual de adicional devido e as diferentes formas de compensação de jornada, como o acordo individual e o banco de horas.","sourceHeading":"3) Trabalho Extraordinário e Compensação de Jornada","pageStart":14,"pageEnd":24,"estimatedStudyMinutes":55,"contentDensity":"MEDIUM","officialTopicId":"work_t6","officialTopicName":"Jornada de trabalho e descansos.","topicCode":"Tópico 06","pageTypes":["MAIN_THEORY","EXPLANATION"],"selectionJustification":"Esta seção do sumário aborda temas correlatos e de alta densidade (horas extras e compensação de jornada), sendo essencial mantê-los juntos como uma unidade pedagógica para a compreensão completa.","isMechanicalCut":false,"isSummaryOnly":false,"isQuestionsOnly":false,"supportType":null,"supportGroupingRationale":null},{"type":"MAIN_BLOCK","title":"Intervalos — intrajornada, interjornada e repouso semanal remunerado","titleQuality":"GOOD","titleRationale":"O título ''Intervalos'' é enriquecido para mencionar os principais tipos de descanso abordados na seção, garantindo clareza e especificidade sobre o conteúdo teórico. Inclui intrajornada, interjornada e RSR, que são os pontos-chave discutidos.","description":"Análise detalhada dos diferentes tipos de intervalos previstos na legislação trabalhista, como o intrajornada (durante a jornada), o interjornada (entre jornadas) e o repouso semanal remunerado, com suas regras e consequências do descumprimento.","sourceHeading":"4) Intervalos","pageStart":25,"pageEnd":47,"estimatedStudyMinutes":60,"contentDensity":"MEDIUM","officialTopicId":"work_t6","officialTopicName":"Jornada de trabalho e descansos.","topicCode":"Tópico 06","pageTypes":["MAIN_THEORY","EXPLANATION"],"selectionJustification":"Conforme o sumário, este bloco cobre integralmente o tema ''Intervalos'', que é um tópico extenso e complexo, merecendo uma unidade de estudo dedicada para cobrir todos os seus subtópicos de forma contínua.","isMechanicalCut":false,"isSummaryOnly":false,"isQuestionsOnly":false,"supportType":null,"supportGroupingRationale":null},{"type":"SUPPORT_BLOCK","title":"Questões Comentadas – Jornada de Trabalho e Intervalos (TRT)","titleQuality":"GOOD","titleRationale":"O título é claro e direto, indicando o tipo de material (''Questões Comentadas'') e o tópico abordado (''Jornada de Trabalho e Intervalos''), além do foco (''TRT''), alinhado ao sumário.","description":"Bloco de apoio composto por questões de concursos anteriores, focadas nos temas de jornada de trabalho e intervalos, com gabaritos e comentários detalhados para auxiliar na revisão e fixação do conteúdo.","sourceHeading":"5) Questões Comentadas - Jornada de Trabalho e Intervalo - TRT","pageStart":48,"pageEnd":103,"estimatedStudyMinutes":0,"contentDensity":"HIGH","officialTopicId":"work_t6","officialTopicName":"Jornada de trabalho e descansos.","topicCode":"Tópico 06","pageTypes":["QUESTIONS","EXPLANATION"],"selectionJustification":"Esta seção é claramente indicada no sumário como ''Questões Comentadas'', configurando um material de apoio distinto da teoria e devendo ser tratada como um bloco de apoio completo.","isMechanicalCut":false,"isSummaryOnly":false,"isQuestionsOnly":true,"supportType":"COMMENTED_QUESTIONS","supportGroupingRationale":"Agrupamento natural de questões comentadas que servem como ferramenta de prática e aprofundamento após o estudo da teoria de Jornada de Trabalho e Intervalos."},{"type":"SUPPORT_BLOCK","title":"Lista de Questões – Jornada de Trabalho e Intervalos (TRT)","titleQuality":"GOOD","titleRationale":"O título é específico, indica que é uma lista de questões (''Lista de Questões'') e detalha os temas (''Jornada de Trabalho e Intervalo'') e o contexto (''TRT''), refletindo fielmente a entrada do sumário.","description":"Bloco de apoio contendo uma lista de questões para que o estudante possa praticar e testar seus conhecimentos sobre os temas de jornada de trabalho e intervalos, visando a preparação para o TRT.","sourceHeading":"6) Lista de Questões - Jornada de Trabalho e Intervalo - TRT","pageStart":104,"pageEnd":129,"estimatedStudyMinutes":0,"contentDensity":"HIGH","off