INSERT INTO "StudyMaterial" ("id", "userId", "fileName", "originalFileName", "filePath", "googleDriveFileId", "mimeType", "fileSize", "totalPages", "sourceType", "sourcePath", "fileHash", "organizationStatus", "detectedSubjectName", "detectedStructure", "processingStatus", "processingError", "subjectId", "createdAt", "updatedAt", "materialRole", "supportForTopicId", "provider") VALUES ('cmpe6xeb10007l5049fx22cwz', 'cmp8od0wz0000iybklaotfqbs', 'direito do trabalho 3.pdf', 'direito do trabalho 3.pdf', NULL, NULL, 'application/pdf', 2992017, 195, 'CLOUD_UPLOAD', 'cmp8od0wz0000iybklaotfqbs/ac96620d-5cba-4b2e-ae1e-16c13a505300.pdf', NULL, 'ORGANIZED', 'Direito do Trabalho', '{"materialRole":"MIXED_MATERIAL","sourceStrategy":"TOC_BASED","tocDetected":true,"tocConfidence":1,"blocks":[{"type":"MAIN_BLOCK","title":"Contrato de Trabalho — Definição, Características e Distinção com Relação de Emprego + Contrato de T","titleQuality":"GOOD","titleRationale":"O título abrange a introdução ao tema, a definição celetista do contrato de trabalho, suas características fundamentais e a importante distinção entre relação de trabalho e relação de emprego, conforme as páginas iniciais do material.","description":"Estudo das bases do contrato de trabalho, suas características essenciais (privado, sinalagmático, consensual, intuitu personae, trato permanente, de atividade e oneroso) e a diferenciação conceitual.","sourceHeading":"1) Definição: Elementos do Contrato de Trabalho","pageStart":3,"pageEnd":20,"estimatedStudyMinutes":60,"contentDensity":"MEDIUM","officialTopicId":"work_t4","officialTopicName":"Contrato de trabalho. Alteração, suspensão e interrupção. Poderes do empregador.","topicCode":"Tópico 04","pageTypes":["MAIN_THEORY","EXPLANATION"],"selectionJustification":"As páginas 3 a 5 do sumário extraído do PDF introduzem o contrato de trabalho, suas definições e características gerais, formando uma unidade temática pedagógica coerente e indivisível como ponto de partida para o estudo do assunto.","isMechanicalCut":false,"isSummaryOnly":false,"isQuestionsOnly":false,"supportType":null,"supportGroupingRationale":null,"mergeRationale":"Backend auto-merged consecutive short blocks of the same topic to reach 45 min target.","isShortBlock":false,"shortBlockJustification":null},{"type":"MAIN_BLOCK","title":"Contrato de Trabalho — Contratos por Prazo Determinado Especiais e Outras Modalidades","titleQuality":"GOOD","titleRationale":"Título genérico, mas pedagógico, para cobrir a continuidade de modalidades contratuais específicas ou menos comuns dentro da seção maior ''Elementos do Contrato de Trabalho'' onde não há sumário interno explícito no extrato.","description":"Discussão sobre outras formas de contrato por prazo determinado não abordadas anteriormente ou modalidades contratuais com características especiais.","sourceHeading":"1) Definição: Elementos do Contrato de Trabalho","pageStart":21,"pageEnd":27,"estimatedStudyMinutes":35,"contentDensity":"MEDIUM","officialTopicId":"work_t4","officialTopicName":"Contrato de trabalho. Alteração, suspensão e interrupção. Poderes do empregador.","topicCode":"Tópico 04","pageTypes":["MAIN_THEORY","EXPLANATION"],"selectionJustification":"Esta unidade temática é inferida para subdividir a seção ''1) Definição: Elementos do Contrato de Trabalho'' (páginas 3-45) em blocos de duração pedagógica adequada (30-60 minutos), mantendo a continuidade temática do contrato de trabalho.","isMechanicalCut":false,"isSummaryOnly":false,"isQuestionsOnly":false,"supportType":null,"supportGroupingRationale":null},{"type":"MAIN_BLOCK","title":"Contrato de Trabalho — Sujeitos, Formas e Efeitos Jurídicos","titleQuality":"GOOD","titleRationale":"Título genérico, mas pedagógico, para cobrir aspectos de sujeitos contratuais, formalidades complementares e os efeitos jurídicos que emanam do contrato de trabalho, dentro de uma seção mais abrangente.","description":"Análise dos atores do contrato de trabalho (empregado e empregador), aspectos adicionais sobre a forma do contrato e as principais consequências jurídicas de sua celebração.","sourceHeading":"1) Definição: Elementos do Contrato de Trabalho","pageStart":28,"pageEnd":34,"estimatedStudyMinutes":35,"contentDensity":"MEDIUM","officialTopicId":"work_t4","officialTopicName":"Contrato de trabalho. Alteração, suspensão e interrupção. Poderes do empregador.","topicCode":"Tópico 04","pageTypes":["MAIN_THEORY","EXPLANATION"],"selectionJustification":"Esta unidade temática é inferida para subdividir a seção ''1) Definição: Elementos do Contrato de Trabalho'' em blocos de duração pedagógica adequada, agrupando conteúdo relacionado a sujeitos e formalidades adicionais do contrato de trabalho.","isMechanicalCut":false,"isSummaryOnly":false,"isQuestionsOnly":false,"supportType":null,"supportGroupingRationale":null},{"type":"MAIN_BLOCK","title":"Contrato de Trabalho — Presunção de Existência e Descaracterização da Relação","titleQuality":"GOOD","titleRationale":"Título genérico, mas pedagógico, para abordar a presunção legal de existência do contrato de trabalho e os elementos que podem levar à descaracterização da relação de emprego, temas complementares ao conceito inicial.","description":"Estudo da presunção de existência da relação de emprego e os fatores que podem descaracterizá-la, como a ausência de subordinação ou pessoalidade, entre outros.","sourceHeading":"1) Definição: Elementos do Contrato de Trabalho","pageStart":35,"pageEnd":40,"estimatedStudyMinutes":30,"contentDensity":"MEDIUM","officialTopicId":"work_t4","officialTopicName":"Contrato de trabalho. Alteração, suspensão e interrupção. Poderes do empregador.","topicCode":"Tópico 04","pageTypes":["MAIN_THEORY","EXPLANATION"],"selectionJustification":"Esta unidade temática é inferida para subdividir a seção ''1) Definição: Elementos do Contrato de Trabalho'' em blocos de duração pedagógica adequada, abordando a presunção legal e a descaracterização da relação de emprego.","isMechanicalCut":false,"isSummaryOnly":false,"isQuestionsOnly":false,"supportType":null,"supportGroupingRationale":null},{"type":"MAIN_BLOCK","title":"Contrato de Trabalho — Interpretação, Princípios Aplicáveis e Súmulas Relevantes","titleQuality":"GOOD","titleRationale":"Título genérico, mas pedagógico, para o fechamento da seção sobre elementos do contrato, consolidando a interpretação do tema, princípios relacionados e súmulas relevantes que complementam o entendimento jurídico.","description":"Revisão e aprofundamento da interpretação do contrato de trabalho, dos princípios jurídicos que o regem e das súmulas e orientações jurisprudenciais pertinentes.","sourceHeading":"1) Definição: Elementos do Contrato de Trabalho","pageStart":41,"pageEnd":45,"estimatedStudyMinutes":30,"contentDensity":"MEDIUM","officialTopicId":"work_t4","officialTopicName":"Contrato de trabalho. Alteração, suspensão e interrupção. Poderes do empregador.","topicCode":"Tópico 04","pageTypes":["MAIN_THEORY","EXPLANATION"],"selectionJustification":"Esta unidade temática é inferida para subdividir a seção ''1) Definição: Elementos do Contrato de Trabalho'' em blocos de duração pedagógica adequada, funcionando como um encerramento conceitual da primeira grande parte do material.","isMechanicalCut":false,"isSummaryOnly":false,"isQuestionsOnly":false,"supportType":null,"supportGroupingRationale":null},{"type":"MAIN_BLOCK","title":"Contrato de Trabalho e CTPS — Formalização, Conteúdo e Anotações","titleQuality":"GOOD","titleRationale":"O título é específico ao abordar a Carteira de Trabalho e Previdência Social (CTPS) em conjunto com o contrato de trabalho, focando nos aspectos de formalização, registro e anotações obrigatórias.","description":"Estudo sobre a CTPS como documento formal do contrato de trabalho, suas características, a obrigatoriedade de anotações e as informações essenciais que devem constar nela.","sourceHeading":"2) Contrato de Trabalho e CTPS","pageStart":46,"pageEnd":52,"estimatedStudyMinutes":35,"contentDensity":"MEDIUM","officialTopicId":"work_t4","officialTopicName":"Contrato de trabalho. Alteração, suspensão e interrupção. Poderes do empregador.","topicCode":"Tópico 04","pageTypes":["MAIN_THEORY","EXPLANATION"],"selectionJustification":"As páginas 46 a 52 introduzem o tópico da CTPS, detalhando sua formalização e a importância das anotações, formando uma unidade temática coerente sobre os aspectos iniciais da carteira de trabalho.","isMechanicalCut":false,"isSummaryOnly":false,"isQuestionsOnly":false,"supportType":null,"supportGroupingRationale":null},{"type":"MAIN_BLOCK","title":"CTPS Digital, Retenção Indevida e Outras Disposições da Carteira de Trabalho","titleQuality":"GOOD","titleRationale":"O título é específico e aborda aspectos complementares e modernos da CTPS, como a versão digital, as penalidades pela retenção indevida e outras disposições legais relevantes para o documento.","description":"Análise da evolução da CTPS para o formato digital, as proibições e penalidades para a retenção indevida do documento físico, e outras regras e súmulas relacionadas à carteira de trabalho.","sourceHeading":"2) Contrato de Trabalho e CTPS","pageStart":53,"pageEnd":58,"estimatedStudyMinutes":30,"contentDensity":"MEDIUM","officialTopicId":"work_t4","officialTopicName":"Contrato de trabalho. Alteração, suspensão e interrupção. Poderes do empregador.","topicCode":"Tópico 04","pageTypes":["MAIN_THEORY","EXPLANATION"],"selectionJustification":"As páginas 53 a 58 complementam o estudo da CTPS, abordando aspectos mais específicos e a atualização para a versão digital, encerrando o tópico ''Contrato de Trabalho e CTPS'' com uma unidade temática coesa.","isMechanicalCut":false,"isSummaryOnly":false,"isQuestionsOnly":false,"supportType":null,"supportGroupingRationale":null},{"type":"SUPPORT_BLOCK","title":"Questões Comentadas — Contrato de Trabalho (TRT)","titleQuality":"GOOD","titleRationale":"O título é claro e direto, indicando que o bloco contém questões de concurso comentadas sobre o tema do contrato de trabalho, extraídas de provas de TRTs.","description":"Compilação de questões de Direito do Trabalho, focadas no tema de Contrato de Trabalho, com comentários detalhados para auxiliar na compreensão e fixação do conteúdo teórico.","sourceHeading":"3) Questões Comentadas - Contrato de Trabalho - TRT","pageStart":59,"pageEnd":153,"estimatedStudyMinutes":0,"contentDensity":"HIGH","officialTopicId":"work_t4","officialTopicName":"Contrato de trabalho. Alteração, suspensão e interrupção. Poderes do empregador.","topicCode":"Tópico 04","pageTypes":["QUESTIONS","COMMENTED_QUESTIONS"],"selectionJustification":"Esta seção é dedicada exclusivamente a questões de concursos comentadas sobre o tema do contrato de trabalho, conforme o sumário fornecido, sendo um material de apoio distinto da teoria principal.","isMechanicalCut":false,"isSummaryOnly":false,"isQuestionsOnly":true,"supportType":"COMMENTED_QUESTIONS","supportGroupingRationale":"Seção dedicada a exercícios para aplicação da teoria estudada, com gabarito comentado para aprendizado."},{"type":"SUPPORT_BLOCK","title":"Lista de Questões — Contrato de Trabalho (TRT)","titleQuality":"GOOD","titleRationale":"O título é preciso, indicando uma lista de questões para prática sobre o Contrato de Trabalho, com foco em provas de TRTs, sem os comentários.","description":"Conjunto de questões de múltipla escolha sobre Direito do Trabalho e Contrato de Trabalho para prática e autoavaliação do conhecimento, ideal para revisão.","sourceHeading":"4) Lista de Questões - Contrato de Trabalho - TRT","pageStart":154,"pageEnd":195,"estimatedStudyMinutes":0,"contentDensity":"HIGH","officialTopicId":"work_t4","officialTopicName":"Contrato de trabalho. Alteração, suspensão e interrupção. Poderes do empregador.","topicCode":"Tópico 04","pageTypes":["QUESTIONS"],"selectionJustification":"Esta seção é dedicada exclusivamente a uma lista de questões para prática sobre o tema do contrato de trabalho, conforme o sumário fornecido, sendo um material de apoio distinto da teoria principal e das questões comentadas.","isMechanicalCut":false,"isSummaryOnly":false,"isQuestionsOnly":true,"supportType":"QUESTIONS","supportGroupingRationale":"Seção dedicada a exercícios para prática e autoavaliação, complementando o estudo teórico e as questões comentadas."}],"aiModelUsed":"gemini-2.5-flash"}', 'PENDING', NULL, 'cmp992nry0001l404o53vsbkj', '2026-05-20T15:02:10.862', '2026-05-20T17:03:18.184', 'MIXED_MATERIAL', NULL, 'OTHER') ON CONFLICT ("id") DO UPDATE SET "userId" = EXCLUDED."userId", "fileName" = EXCLUDED."fileName", "originalFileName" = EXCLUDED."originalFileName", "filePath" = EXCLUDED."filePath", "googleDriveFileId" = EXCLUDED."googleDriveFileId", "mimeType" = EXCLUDED."mimeType", "fileSize" = EXCLUDED."fileSize", "totalPages" = EXCLUDED."totalPages", "sourceType" = EXCLUDED."sourceType", "sourcePath" = EXCLUDED."sourcePath", "fileHash" = EXCLUDED."fileHash", "organizationStatus" = EXCLUDED."organizationStatus", "detectedSubjectName" = EXCLUDED."detectedSubjectName", "detectedStructure" = EXCLUDED."detectedStructure", "processingStatus" = EXCLUDED."processingStatus", "processingError" = EXCLUDED."processingError", "subjectId" = EXCLUDED."subjectId", "createdAt" = EXCLUDED."createdAt", "updatedAt" = EXCLUDED."updatedAt", "materialRole" = EXCLUDED."materialRole", "supportForTopicId" = EXCLUDED."supportForTopicId", "provider" = EXCLUDED."provider";
INSERT INTO "StudyMaterial" ("id", "userId", "fileName", "originalFileName", "filePath", "googleDriveFileId", "mimeType", "fileSize", "totalPages", "sourceType", "sourcePath", "fileHash", "organizationStatus", "detectedSubjectName", "detectedStructure", "processingStatus", "processingError", "subjectId", "createdAt", "updatedAt", "materialRole", "supportForTopicId", "provider") VALUES ('cmpe6x9z70005l504gzwkl5im', 'cmp8od0wz0000iybklaotfqbs', 'processual civil 3.pdf', 'processual civil 3.pdf', NULL, NULL, 'application/pdf', 994373, 87, 'CLOUD_UPLOAD', 'cmp8od0wz0000iybklaotfqbs/4f1936a6-43a6-4f99-b333-3f071ec79d2a.pdf', NULL, 'ORGANIZED', 'Direito Processual Civil', '{"materialRole":"MAIN_MATERIAL","sourceStrategy":"TOC_BASED","tocDetected":true,"tocConfidence":1,"blocks":[{"type":"MAIN_BLOCK","title":"Capacidades — capacidade de ser parte, de estar em juízo e postulatória","titleQuality":"GOOD","titleRationale":"Este título é específico e abrange as três capacidades processuais distintas tratadas no início do conteúdo, conforme detalhado na estrutura do sumário.","description":"Estudo das diferentes capacidades relacionadas aos sujeitos do processo: capacidade de ser parte (personalidade judiciária), capacidade de estar em juízo (exercício dos atos processuais) e capacidade postulatória (representação por advogado).","sourceHeading":"Capacidades","pageStart":5,"pageEnd":11,"estimatedStudyMinutes":56,"contentDensity":"HIGH","officialTopicId":"proc_civil_t3","officialTopicName":"Sujeitos Processuais: Partes e Procuradores. Litisconsórcio e Intervenção de terceiros.","topicCode":"Tópico 03","pageTypes":["MAIN_THEORY","EXPLANATION"],"selectionJustification":"As páginas 5 a 11 tratam de forma unificada e conceitual sobre as distintas capacidades processuais (ser parte, estar em juízo, postulatória), que são a base para a compreensão das partes e seus procuradores. A divisão respeita o início natural do assunto no sumário e a continuidade temática.","isMechanicalCut":false,"isSummaryOnly":false,"isQuestionsOnly":false,"supportType":null,"supportGroupingRationale":null},{"type":"MAIN_BLOCK","title":"Representação e Assistência de Incapazes e Citações Fictas + Pessoas Jurídicas e Entes Sem Personali","titleQuality":"GOOD","titleRationale":"Este título agrupa a explicação sobre como os incapazes são representados ou assistidos e a nomeação de curador especial para réus presos revel ou citados por edital/hora certa, conforme detalhado na parte ''Capacidade de estar em juízo''.","description":"Análise do regime de representação e assistência para pessoas incapazes (absoluta ou relativamente incapazes), a função do curador especial e as situações em que este é nomeado, incluindo réus revel c","sourceHeading":"Capacidade de estar em juízo","pageStart":6,"pageEnd":14,"estimatedStudyMinutes":60,"contentDensity":"HIGH","officialTopicId":"proc_civil_t3","officialTopicName":"Sujeitos Processuais: Partes e Procuradores. Litisconsórcio e Intervenção de terceiros.","topicCode":"Tópico 03","pageTypes":["MAIN_THEORY","EXPLANATION"],"selectionJustification":"As páginas 6 a 9 detalham a aplicação prática da ''capacidade de estar em juízo'' para incapazes e a figura do curador especial em casos de revelia após citação ficta, formando uma unidade temática coesa dentro da seção maior de ''Capacidades''.","isMechanicalCut":false,"isSummaryOnly":false,"isQuestionsOnly":false,"supportType":null,"supportGroupingRationale":null,"mergeRationale":"Backend auto-merged consecutive short blocks of the same topic to reach 45 min target.","isShortBlock":false,"shortBlockJustification":null},{"type":"MAIN_BLOCK","title":"Responsabilidade por Dano Processual, Despesas, Honorários e Gratuidade da Justiça","titleQuality":"GOOD","titleRationale":"Este título abrange os temas relacionados à responsabilidade financeira e custos processuais, incluindo dano processual, despesas, honorários e gratuidade da justiça.","description":"Análise da responsabilidade das partes por dano processual, a disciplina sobre despesas processuais, honorários advocatícios, multas e as regras para concessão da gratuidade da justiça.","sourceHeading":"Deveres das partes e de seus procuradores","pageStart":15,"pageEnd":24,"estimatedStudyMinutes":60,"contentDensity":"HIGH","officialTopicId":"proc_civil_t3","officialTopicName":"Sujeitos Processuais: Partes e Procuradores. Litisconsórcio e Intervenção de terceiros.","topicCode":"Tópico 03","pageTypes":["MAIN_THEORY","EXPLANATION"],"selectionJustification":"As páginas 15 a 24 tratam de forma integrada sobre responsabilidade por dano processual, despesas, honorários e gratuidade da justiça. Embora sejam subtemas, estão sob o guarda-chuva do item 2 do sumário (''Deveres das partes e de seus procuradores'') e formam uma unidade temática sobre os custos e responsabilidades financeiras do processo.","isMechanicalCut":false,"isSummaryOnly":false,"isQuestionsOnly":false,"supportType":null,"supportGroupingRationale":null},{"type":"MAIN_BLOCK","title":"Procuradores — Nomeação, Poderes e Deveres + Sucessão das Partes e dos Procuradores no Processo + Li","titleQuality":"GOOD","titleRationale":"Este título descreve o conteúdo sobre os procuradores, incluindo sua nomeação, os poderes que detêm e seus deveres no processo.","description":"Estudo da figura dos procuradores no processo civil, abordando sua atuação, os poderes conferidos pela procuração e os deveres que lhes são impostos pela lei. | Análise das hipóteses e do procedimento","sourceHeading":"Procuradores","pageStart":28,"pageEnd":39,"estimatedStudyMinutes":60,"contentDensity":"MEDIUM","officialTopicId":"proc_civil_t3","officialTopicName":"Sujeitos Processuais: Partes e Procuradores. Litisconsórcio e Intervenção de terceiros.","topicCode":"Tópico 03","pageTypes":["MAIN_THEORY","EXPLANATION"],"selectionJustification":"As páginas 28 a 30 tratam especificamente dos procuradores, um subitem do item ''Partes e Procuradores'' do sumário, formando uma unidade temática sobre a representação técnica no processo.","isMechanicalCut":false,"isSummaryOnly":false,"isQuestionsOnly":false,"supportType":null,"supportGroupingRationale":null,"mergeRationale":"Backend auto-merged consecutive short blocks of the same topic to reach 45 min target.","isShortBlock":false,"shortBlockJustification":null},{"type":"MAIN_BLOCK","title":"Intervenção de Terceiros — Classificação, Espécies e Procedimentos","titleQuality":"GOOD","titleRationale":"Este título abrange o tema ''Intervenção de Terceiros'', cobrindo sua classificação geral, as diversas modalidades e os procedimentos para sua efetivação.","description":"Análise das modalidades de intervenção de terceiros no processo civil, como assistência, denunciação da lide, chamamento ao processo, incidente de desconsideração da personalidade jurídica e amicus curiae, com seus respectivos procedimentos.","sourceHeading":"Intervenção de Terceiros","pageStart":40,"pageEnd":50,"estimatedStudyMinutes":60,"contentDensity":"HIGH","officialTopicId":"proc_civil_t3","officialTopicName":"Sujeitos Processuais: Partes e Procuradores. Litisconsórcio e Intervenção de terceiros.","topicCode":"Tópico 03","pageTypes":["MAIN_THEORY","EXPLANATION"],"selectionJustification":"As páginas 40 a 50 cobrem exaustivamente o tema ''Intervenção de Terceiros'', detalhando suas espécies (assistência, denunciação da lide, chamamento ao processo, desconsideração da personalidade jurídica, amicus curiae) e procedimentos, constituindo uma unidade temática completa do sumário.","isMechanicalCut":false,"isSummaryOnly":false,"isQuestionsOnly":false,"supportType":null,"supportGroupingRationale":null},{"type":"SUPPORT_BLOCK","title":"Questões Comentadas: Partes e Procuradores","titleQuality":"GOOD","titleRationale":"Título descritivo para questões comentadas focadas no tema ''Partes e Procuradores''.","description":"Conjunto de questões de concursos anteriores comentadas sobre o tema ''Partes e Procuradores''.","sourceHeading":"Questões Comentadas",