INSERT INTO "StudyMaterial" ("id", "userId", "fileName", "originalFileName", "filePath", "googleDriveFileId", "mimeType", "fileSize", "totalPages", "sourceType", "sourcePath", "fileHash", "organizationStatus", "detectedSubjectName", "detectedStructure", "processingStatus", "processingError", "subjectId", "createdAt", "updatedAt", "materialRole", "supportForTopicId", "provider") VALUES ('cmq6lzlly000bii04xuv2ujcn', 'cmpvqi7bp0000kz043wp09yja', 'modulo3_atualizado.pdf', 'modulo3_atualizado.pdf', NULL, NULL, 'application/pdf', 3354556, 121, 'CLOUD_UPLOAD', 'cmpvqi7bp0000kz043wp09yja/83e1a064-cdec-4c5c-8aba-5e115d796b55.pdf', NULL, 'ORGANIZED', 'Informática', '{"materialRole":"MAIN_MATERIAL","sourceStrategy":"HYBRID","tocDetected":false,"tocConfidence":0,"blocks":[{"type":"MAIN_BLOCK","title":"Entendendo os Controles de Segurança — Fundamentos e Tipos de Medidas","titleQuality":"GOOD","titleRationale":"O título é específico e abrange os fundamentos dos controles de segurança e suas classificações, conforme a ''Parte 1'' do material.","description":"Introduz os fundamentos dos controles de segurança da informação, sua importância, origem em frameworks como ISO/IEC 27001 e a classificação detalhada dos tipos de medidas preventivas, detectivas, corretivas, redutivas, repressivas, seguros e aceitação.","sourceHeading":"Parte 1 – Entendendo os controles de segurança","pageStart":4,"pageEnd":25,"estimatedStudyMinutes":60,"contentDensity":"MEDIUM","officialTopicId":null,"officialTopicName":"Tópico não identificado","topicCode":"GERAL","pageTypes":["MAIN_THEORY","EXPLANATION"],"selectionJustification":"Unidade temática que define a base teórica e as categorias dos controles de segurança, conforme a estrutura da ''Parte 1'' do módulo, com início explícito na página 4 e duração pedagógica coerente.","isMechanicalCut":false,"isSummaryOnly":false,"isQuestionsOnly":false,"supportType":null,"supportGroupingRationale":null},{"type":"MAIN_BLOCK","title":"Controles Organizacionais — Gestão de Identidade e Acesso","titleQuality":"GOOD","titleRationale":"O título é específico para controles organizacionais e um tópico central evidenciado, como gestão de identidade e acesso (página 30).","description":"Examina os controles de segurança implementados no nível organizacional, abordando a formulação de políticas, a estrutura de gestão da segurança, a segurança da cadeia de suprimentos e, especificamente, o gerenciamento de identidade e acesso de usuários para garantir a proteção dos ativos de informação.","sourceHeading":"Parte 2 – Controles organizacionais","pageStart":26,"pageEnd":40,"estimatedStudyMinutes":60,"contentDensity":"MEDIUM","officialTopicId":null,"officialTopicName":"Tópico não identificado","topicCode":"GERAL","pageTypes":["MAIN_THEORY","EXPLANATION"],"selectionJustification":"Unidade temática que foca nos aspectos de governança e políticas de segurança, bem como na gestão de acesso, seguindo a lógica da ''Parte 2'' do módulo e evidências do conteúdo na página 30.","isMechanicalCut":false,"isSummaryOnly":false,"isQuestionsOnly":false,"supportType":null,"supportGroupingRationale":null},{"type":"MAIN_BLOCK","title":"Controle de Pessoas — Conscientização e Resposta a Incidentes","titleQuality":"GOOD","titleRationale":"O título reflete a ''Parte 3'' do módulo, associando o controle de pessoas à conscientização e à resposta a incidentes, um tópico presente no conteúdo (página 45).","description":"Detalha a importância do elemento humano na segurança da informação, explorando a conscientização, treinamento, responsabilidades dos funcionários e a metodologia de resposta a incidentes de segurança, incluindo a definição de níveis de severidade.","sourceHeading":"Parte 3 – Controle de pessoas","pageStart":41,"pageEnd":55,"estimatedStudyMinutes":60,"contentDensity":"MEDIUM","officialTopicId":null,"officialTopicName":"Tópico não identificado","topicCode":"GERAL","pageTypes":["MAIN_THEORY","EXPLANATION"],"selectionJustification":"Aborda os controles relacionados ao comportamento humano e às ações em caso de incidentes, conforme sugerido pela ''Parte 3'' do módulo e pelos conteúdos da página 45, formando uma unidade pedagógica coesa.","isMechanicalCut":false,"isSummaryOnly":false,"isQuestionsOnly":false,"supportType":null,"supportGroupingRationale":null},{"type":"MAIN_BLOCK","title":"Controles Físicos — Proteção de Áreas e Equipamentos","titleQuality":"GOOD","titleRationale":"O título é claro e específico para ''Controles Físicos'', complementando com o escopo de proteção de áreas e equipamentos, conforme a ''Parte 4'' do material.","description":"Cobre as medidas de segurança física projetadas para proteger áreas, instalações e equipamentos contra acessos não autorizados, danos ou interferências. Inclui conceitos como perímetro de segurança, barreiras arquitetônicas e proteção de infraestrutura, como evidenciado na página 60 (''Anel externo'').","sourceHeading":"Parte 4 – Controles físicos","pageStart":56,"pageEnd":74,"estimatedStudyMinutes":60,"contentDensity":"MEDIUM","officialTopicId":null,"officialTopicName":"Tópico não identificado","topicCode":"GERAL","pageTypes":["MAIN_THEORY","EXPLANATION"],"selectionJustification":"Esta unidade temática concentra-se exclusivamente nos controles de segurança física, correspondendo à ''Parte 4'' do módulo, com o início do tópico claramente detectado na página 60 e encerra-se antes do início explícito da próxima parte.","isMechanicalCut":false,"isSummaryOnly":false,"isQuestionsOnly":false,"supportType":null,"supportGroupingRationale":null},{"type":"MAIN_BLOCK","title":"Controles Técnicos (Parte I) — Segurança de Redes e Gerenciamento de Vulnerabilidades","titleQuality":"GOOD","titleRationale":"O título divide a seção de ''Controles Técnicos'' em duas partes devido à extensão e foca na segurança de redes e no gerenciamento de vulnerabilidades, incluindo malware (página 90).","description":"Inicia a discussão sobre os controles de segurança baseados em tecnologia, focando na segurança de redes, firewalls, sistemas de detecção de intrusão, segurança de sistemas operacionais e o gerenciamento de vulnerabilidades e ameaças como malware e worms.","sourceHeading":"Parte 5 – Controles técnicos (ou de tecnologia)","pageStart":75,"pageEnd":97,"estimatedStudyMinutes":60,"contentDensity":"MEDIUM","officialTopicId":null,"officialTopicName":"Tópico não identificado","topicCode":"GERAL","pageTypes":["MAIN_THEORY","EXPLANATION"],"selectionJustification":"Representa a primeira porção da ''Parte 5'', dedicada aos controles técnicos, agrupando tópicos de segurança de rede, sistemas e a introdução a ameaças cibernéticas, com um início claro na página 75 e uma divisão pedagógica para evitar blocos excessivamente longos.","isMechanicalCut":false,"isSummaryOnly":false,"isQuestionsOnly":false,"supportType":null,"supportGroupingRationale":null},{"type":"MAIN_BLOCK","title":"Controles Técnicos (Parte II) — Proteção de Dados e Criptografia","titleQuality":"GOOD","titleRationale":"O título complementa a primeira parte dos controles técnicos, abordando tópicos específicos como prevenção de vazamento de dados (página 105) e criptografia (página 120).","description":"Continua a abordagem dos controles técnicos, aprofundando-se na prevenção de vazamento de dados (DLP), uso e gerenciamento de criptografia, controles de acesso lógico e segurança de aplicações, concluindo o módulo.","sourceHeading":"Parte 5 – Controles técnicos (ou de tecnologia)","pageStart":98,"pageEnd":121,"estimatedStudyMinutes":60,"contentDensity":"MEDIUM","officialTopicId":null,"officialTopicName":"Tópico não identificado","topicCode":"GERAL","pageTypes":["MAIN_THEORY","EXPLANATION"],"selectionJustification":"Complementa a ''Parte 5'' ao cobrir os controles técnicos mais avançados relacionados à proteção de dados em trânsito e em repouso, e o gerenciamento de chaves criptográficas até o final do material, formando uma unidade temática coerente e finalizando o conteúdo.","isMechanicalCut":false,"