INSERT INTO "Flashcard" ("id", "userId", "subjectId", "contentId", "materialId", "studyBlockId", "question", "answer", "type", "difficulty", "status", "reviewState", "learningStep", "easeFactor", "intervalDays", "repetitionCount", "lapseCount", "lastReviewedAt", "nextReviewAt", "approvedAt", "sourcePageStart", "sourcePageEnd", "createdAt", "updatedAt", "generationReason") VALUES ('cmpgygih5005xiym0cnku6dud', 'cmp8od0wz0000iybklaotfqbs', 'cmp992nry0001l404o53vsbkj', NULL, NULL, NULL, 'As anotações na CTPS geram presunção absoluta de veracidade?', 'Não. Geram presunção JURIS TANTUM (relativa), podendo ser elididas por prova em contrário (Súmula 12 do TST).', 'QUESTION_ANSWER', 'MEDIUM', 'APPROVED', 'REVIEW', 0, 3.1, 30, 8, 1, '2026-07-18T00:29:12.188', '2026-08-17T00:00:00', '2026-05-22T13:28:24.62', NULL, NULL, '2026-05-22T13:28:24.641', '2026-07-18T00:29:12.189', NULL) ON CONFLICT ("id") DO UPDATE SET "userId" = EXCLUDED."userId", "subjectId" = EXCLUDED."subjectId", "contentId" = EXCLUDED."contentId", "materialId" = EXCLUDED."materialId", "studyBlockId" = EXCLUDED."studyBlockId", "question" = EXCLUDED."question", "answer" = EXCLUDED."answer", "type" = EXCLUDED."type", "difficulty" = EXCLUDED."difficulty", "status" = EXCLUDED."status", "reviewState" = EXCLUDED."reviewState", "learningStep" = EXCLUDED."learningStep", "easeFactor" = EXCLUDED."easeFactor", "intervalDays" = EXCLUDED."intervalDays", "repetitionCount" = EXCLUDED."repetitionCount", "lapseCount" = EXCLUDED."lapseCount", "lastReviewedAt" = EXCLUDED."lastReviewedAt", "nextReviewAt" = EXCLUDED."nextReviewAt", "approvedAt" = EXCLUDED."approvedAt", "sourcePageStart" = EXCLUDED."sourcePageStart", "sourcePageEnd" = EXCLUDED."sourcePageEnd", "createdAt" = EXCLUDED."createdAt", "updatedAt" = EXCLUDED."updatedAt", "generationReason" = EXCLUDED."generationReason";
INSERT INTO "Flashcard" ("id", "userId", "subjectId", "contentId", "materialId", "studyBlockId", "question", "answer", "type", "difficulty", "status", "reviewState", "learningStep", "easeFactor", "intervalDays", "repetitionCount", "lapseCount", "lastReviewedAt", "nextReviewAt", "approvedAt", "sourcePageStart", "sourcePageEnd", "createdAt", "updatedAt", "generationReason") VALUES ('cmrif88vl0011jr047ljfltl4', 'cmp8od0wz0000iybklaotfqbs', 'cmp9zspkj0059l204sz3mezxt', NULL, NULL, NULL, 'Quais princípios impõem que o magistrado julgue o mérito estritamente nos limites traçados pelas partes na petição inicial?', 'Princípios da adstrição (ou congruência) e dispositivo[cite: 19].', 'QUESTION_ANSWER', 'MEDIUM', 'APPROVED', 'REVIEW', 0, 2.8, 10, 7, 1, '2026-07-27T21:27:56.417', '2026-08-06T00:00:00', '2026-07-12T23:25:03.319', NULL, NULL, '2026-07-12T23:25:03.326', '2026-07-27T21:27:56.418', NULL) ON CONFLICT ("id") DO UPDATE SET "userId" = EXCLUDED."userId", "subjectId" = EXCLUDED."subjectId", "contentId" = EXCLUDED."contentId", "materialId" = EXCLUDED."materialId", "studyBlockId" = EXCLUDED."studyBlockId", "question" = EXCLUDED."question", "answer" = EXCLUDED."answer", "type" = EXCLUDED."type", "difficulty" = EXCLUDED."difficulty", "status" = EXCLUDED."status", "reviewState" = EXCLUDED."reviewState", "learningStep" = EXCLUDED."learningStep", "easeFactor" = EXCLUDED."easeFactor", "intervalDays" = EXCLUDED."intervalDays", "repetitionCount" = EXCLUDED."repetitionCount", "lapseCount" = EXCLUDED."lapseCount", "lastReviewedAt" = EXCLUDED."lastReviewedAt", "nextReviewAt" = EXCLUDED."nextReviewAt", "approvedAt" = EXCLUDED."approvedAt", "sourcePageStart" = EXCLUDED."sourcePageStart", "sourcePageEnd" = EXCLUDED."sourcePageEnd", "createdAt" = EXCLUDED."createdAt", "updatedAt" = EXCLUDED."updatedAt", "generationReason" = EXCLUDED."generationReason";
INSERT INTO "Flashcard" ("id", "userId", "subjectId", "contentId", "materialId", "studyBlockId", "question", "answer", "type", "difficulty", "status", "reviewState", "learningStep", "easeFactor", "intervalDays", "repetitionCount", "lapseCount", "lastReviewedAt", "nextReviewAt", "approvedAt", "sourcePageStart", "sourcePageEnd", "createdAt", "updatedAt", "generationReason") VALUES ('cmrif88vj000ljr04gta8h950', 'cmp8od0wz0000iybklaotfqbs', 'cmp992nry0001l404o53vsbkj', NULL, NULL, NULL, 'No exercício do poder disciplinar pelo empregador, qual a consequência jurídica se a suspensão aplicada ao empregado for superior a 30 dias consecutivos?', 'Importa na rescisão injusta (indireta) do contrato de trabalho por parte do empregador (Art. 474 da CLT)[cite: 14].', 'QUESTION_ANSWER', 'MEDIUM', 'APPROVED', 'REVIEW', 0, 2.65, 13, 3, 0, '2026-07-22T22:43:06.052', '2026-08-04T00:00:00', '2026-07-12T23:25:03.318', NULL, NULL, '2026-07-12T23:25:03.326', '2026-07-22T22:43:06.053', NULL) ON CONFLICT ("id") DO UPDATE SET "userId" = EXCLUDED."userId", "subjectId" = EXCLUDED."subjectId", "contentId" = EXCLUDED."contentId", "materialId" = EXCLUDED."materialId", "studyBlockId" = EXCLUDED."studyBlockId", "question" = EXCLUDED."question", "answer" = EXCLUDED."answer", "type" = EXCLUDED."type", "difficulty" = EXCLUDED."difficulty", "status" = EXCLUDED."status", "reviewState" = EXCLUDED."reviewState", "learningStep" = EXCLUDED."learningStep", "easeFactor" = EXCLUDED."easeFactor", "intervalDays" = EXCLUDED."intervalDays", "repetitionCount" = EXCLUDED."repetitionCount", "lapseCount" = EXCLUDED."lapseCount", "lastReviewedAt" = EXCLUDED."lastReviewedAt", "nextReviewAt" = EXCLUDED."nextReviewAt", "approvedAt" = EXCLUDED."approvedAt", "sourcePageStart" = EXCLUDED."sourcePageStart", "sourcePageEnd" = EXCLUDED."sourcePageEnd", "createdAt" = EXCLUDED."createdAt", "updatedAt" = EXCLUDED."updatedAt", "generationReason" = EXCLUDED."generationReason";
INSERT INTO "Flashcard" ("id", "userId", "subjectId", "contentId", "materialId", "studyBlockId", "question", "answer", "type", "difficulty", "status", "reviewState", "learningStep", "easeFactor", "intervalDays", "repetitionCount", "lapseCount", "lastReviewedAt", "nextReviewAt", "approvedAt", "sourcePageStart", "sourcePageEnd", "createdAt", "updatedAt", "generationReason") VALUES ('cmrif88vk000rjr040fx0ti7f', 'cmp8od0wz0000iybklaotfqbs', 'cmp9zspkj0059l204sz3mezxt', NULL, NULL, NULL, 'O juiz pode decidir com base em fundamento sobre o qual as partes não se manifestaram se a matéria for de ordem pública (cognoscível de ofício)?', 'Não. O art. 10 do CPC veda a decisão surpresa, exigindo prévia manifestação das partes ainda que se trate de matéria sobre a qual deva decidir de ofício.', 'QUESTION_ANSWER', 'MEDIUM', 'APPROVED', 'REVIEW', 0, 2.65, 13, 3, 0, '2026-07-22T22:43:22.082', '2026-08-04T00:00:00', '2026-07-12T23:25:03.319', NULL, NULL, '2026-07-12T23:25:03.326', '2026-07-22T22:43:22.084', NULL) ON CONFLICT ("id") DO UPDATE SET "userId" = EXCLUDED."userId", "subjectId" = EXCLUDED."subjectId", "contentId" = EXCLUDED."contentId", "materialId" = EXCLUDED."materialId", "studyBlockId" = EXCLUDED."studyBlockId", "question" = EXCLUDED."question", "answer" = EXCLUDED."answer", "type" = EXCLUDED."type", "difficulty" = EXCLUDED."difficulty", "status" = EXCLUDED."status", "reviewState" = EXCLUDED."reviewState", "learningStep" = EXCLUDED."learningStep", "easeFactor" = EXCLUDED."easeFactor", "intervalDays" = EXCLUDED."intervalDays", "repetitionCount" = EXCLUDED."repetitionCount", "lapseCount" = EXCLUDED."lapseCount", "lastReviewedAt" = EXCLUDED."lastReviewedAt", "nextReviewAt" = EXCLUDED."nextReviewAt", "approvedAt" = EXCLUDED."approvedAt", "sourcePageStart" = EXCLUDED."sourcePageStart", "sourcePageEnd" = EXCLUDED."sourcePageEnd", "createdAt" = EXCLUDED."createdAt", "updatedAt" = EXCLUDED."updatedAt", "generationReason" = EXCLUDED."generationReason";
INSERT INTO "Flashcard" ("id", "userId", "subjectId", "contentId", "materialId", "studyBlockId", "question", "answer", "type", "difficulty", "status", "reviewState", "learningStep", "easeFactor", "intervalDays", "repetitionCount", "lapseCount", "lastReviewedAt", "nextReviewAt", "approvedAt", "sourcePageStart", "sourcePageEnd", "createdAt", "updatedAt", "generationReason") VALUES ('cmrif88vl0013jr04wqxn3bz4', 'cmp8od0wz0000iybklaotfqbs', 'cmp9zspkj0059l204sz3mezxt', NULL, NULL, NULL, 'Na ausência de norma regulamentadora específica, as disposições do CPC aplicam-se a processos eleitorais, trabalhistas ou administrativos de que forma?', 'Aplicam-se de forma SUPLETIVA (omissão total) e SUBSIDIÁRIA (omissão parcial), conforme o art. 15 do CPC[cite: 20].', 'QUESTION_ANSWER', 'MEDIUM', 'APPROVED', 'REVIEW', 0, 2.65, 13, 3, 0, '2026-07-22T22:43:40.864', '2026-08-04T00:00:00', '2026-07-12T23:25:03.319', NULL, NULL, '2026-07-12T23:25:03.326', '2026-07-22T22:43:40.865', NULL) ON CONFLICT ("id") DO UPDATE SET "userId" = EXCLUDED."userId", "subjectId" = EXCLUDED."subjectId", "contentId" = EXCLUDED."contentId", "materialId" = EXCLUDED."materialId", "studyBlockId" = EXCLUDED."studyBlockId", "question" = EXCLUDED."question", "answer" = EXCLUDED."answer", "type" = EXCLUDED."type", "difficulty" = EXCLUDED."difficulty", "status" = EXCLUDED."status", "reviewState" = EXCLUDED."reviewState", "learningStep" = EXCLUDED."learningStep", "easeFactor" = EXCLUDED."easeFactor", "intervalDays" = EXCLUDED."intervalDays", "repetitionCount" = EXCLUDED."repetitionCount", "lapseCount" = EXCLUDED."lapseCount", "lastReviewedAt" = EXCLUDED."lastReviewedAt", "nextReviewAt" = EXCLUDED."nextReviewAt", "approvedAt" = EXCLUDED."approvedAt", "sourcePageStart" = EXCLUDED."sourcePageStart", "sourcePageEnd" = EXCLUDED."sourcePageEnd", "createdAt" = EXCLUDED."createdAt", "updatedAt" = EXCLUDED."updatedAt", "generationReason" = EXCLUDED."generationReason";
INSERT INTO "Flashcard" ("id", "userId", "subjectId", "contentId", "materialId", "studyBlockId", "question", "answer", "type", "difficulty", "status", "reviewState", "learningStep", "easeFactor", "intervalDays", "repetitionCount", "lapseCount", "lastReviewedAt", "nextReviewAt", "approvedAt", "sourcePageStart", "sourcePageEnd", "createdAt", "updatedAt", "generationReason") VALUES ('cmrif88vl0017jr04ykuj66gr', 'cmp8od0wz0000iybklaotfqbs', 'cmp992nry0001l404o53vsbkj', NULL, NULL, NULL, 'O afastamento de empregado em razão de sua eleição para o cargo de diretor de Sociedade Anônima (S/A) gera qual efeito contratual?', 'Em regra gera a suspensão do contrato, SALVO se permanecer a subordinação jurídica inerente à relação de emprego (Súmula 269 do TST)[cite: 21].', 'QUESTION_ANSWER', 'MEDIUM', 'APPROVED', 'REVIEW', 0, 2.65, 13, 3, 0, '2026-07-22T22:43:59.793', '2026-08-04T00:00:00', '2026-07-12T23:25:03.32', NULL, NULL, '2026-07-12T23:25:03.326', '2026-07-22T22:43:59.794', NULL) ON CONFLICT ("id") DO UPDATE SET "userId" = EXCLUDED."userId", "subjectId" = EXCLUDED."subjectId", "contentId" = EXCLUDED."contentId", "materialId" = EXCLUDED."materialId", "studyBlockId" = EXCLUDED."studyBlockId", "question" = EXCLUDED."question", "answer" = EXCLUDED."answer", "type" = EXCLUDED."type", "difficulty" = EXCLUDED."difficulty", "status" = EXCLUDED."status", "reviewState" = EXCLUDED."reviewState", "learningStep" = EXCLUDED."learningStep", "easeFactor" = EXCLUDED."easeFactor", "intervalDays" = EXCLUDED."intervalDays", "repetitionCount" = EXCLUDED."repetitionCount", "lapseCount" = EXCLUDED."lapseCount", "lastReviewedAt" = EXCLUDED."lastReviewedAt", "nextReviewAt" = EXCLUDED."nextReviewAt", "approvedAt" = EXCLUDED."approvedAt", "sourcePageStart" = EXCLUDED."sourcePageStart", "sourcePageEnd" = EXCLUDED."sourcePageEnd", "createdAt" = EXCLUDED."createdAt", "updatedAt" = EXCLUDED."updatedAt", "generationReason" = EXCLUDED."generationReason";
INSERT INTO "Flashcard" ("id", "userId", "subjectId", "contentId", "materialId", "studyBlockId", "question", "answer", "type", "difficulty", "status", "reviewState", "learningStep", "easeFactor", "intervalDays", "repetitionCount", "lapseCount", "lastReviewedAt", "nextReviewAt", "approvedAt", "sourcePageStart", "sourcePageEnd", "createdAt", "updatedAt", "generationReason") VALUES ('cmrif88vj000jjr04rko0zdxy', 'cmp8od0wz0000iybklaotfqbs', 'cmp992nry0001l404o53vsbkj', NULL, NULL, NULL, 'O reconhecimento da relação de emprego depende da denominação jurídica ou do contrato formalizado pelas partes?', 'Não. Vigora o Princípio da Primazia da Realidade, pelo qual a verdade real dos fatos prevalece sobre as formalidades contratuais (Art. 9º da CLT)[cite: 12].', 'QUESTION_ANSWER', 'MEDIUM', 'APPROVED', 'REVIEW', 0, 2.65, 13, 4, 0, '2026-07-22T22:44:17.022', '2026-08-04T00:00:00', '2026-07-12T23:25:03.318', NULL, NULL, '2026-07-12T23:25:03.326', '2026-07-22T22:44:17.023', NULL) ON CONFLICT ("id") DO UPDATE SET "userId" = EXCLUDED."userId", "subjectId" = EXCLUDED."subjectId", "contentId" = EXCLUDED."contentId", "materialId" = EXCLUDED."materialId", "studyBlockId" = EXCLUDED."studyBlockId", "question" = EXCLUDED."question", "answer" = EXCLUDED."answer", "type" = EXCLUDED."type", "difficulty" = EXCLUDED."difficulty", "status" = EXCLUDED."status", "reviewState" = EXCLUDED."reviewState", "learningStep" = EXCLUDED."learningStep", "easeFactor" = EXCLUDED."easeFactor", "intervalDays" = EXCLUDED."intervalDays", "repetitionCount" = EXCLUDED."repetitionCount", "lapseCount" = EXCLUDED."lapseCount", "lastReviewedAt" = EXCLUDED."lastReviewedAt", "nextReviewAt" = EXCLUDED."nextReviewAt", "approvedAt" = EXCLUDED."approvedAt", "sourcePageStart" = EXCLUDED."sourcePageStart", "sourcePageEnd" = EXCLUDED."sourcePageEnd", "createdAt" = EXCLUDED."createdAt", "updatedAt" = EXCLUDED."updatedAt", "generationReason" = EXCLUDED."generationReason";
INSERT INTO "Flashcard" ("id", "userId", "subjectId", "contentId", "materialId", "studyBlockId", "question", "answer", "type", "difficulty", "status", "reviewState", "learningStep", "easeFactor", "intervalDays", "repetitionCount", "lapseCount", "lastReviewedAt", "nextReviewAt", "approvedAt", "sourcePageStart", "sourcePageEnd", "createdAt", "updatedAt", "generationReason") VALUES ('cmq1hfxnw0009l504qzg78sce', 'cmp8od0wz0000iybklaotfqbs', 'cmp9zspkj0059l204sz3mezxt', NULL, 'cmpd3ri47000zlh04hu5rnc9b', 'cmpd4a6q400gblh04skokxthl', 'Quais as duas exceções ao princípio da indelegabilidade da jurisdição?', 'Carta de ordem para atos de instrução em ações originárias de 2º grau e execução de julgados do STF por juiz de 1º grau.', 'QUESTION_ANSWER', 'MEDIUM', 'APPROVED', 'REVIEW', 0, 3.25, 16, 11, 2, '2026-07-23T22:45:36.059', '2026-08-08T00:00:00', '2026-06-05T22:15:13.956', 3, 13, '2026-06-05T22:15:13.958', '2026-07-23T22:45:36.06', NULL) ON CONFLICT ("id") DO UPDATE SET "userId" = EXCLUDED."userId", "subjectId" = EXCLUDED."subjectId", "contentId" = EXCLUDED."contentId", "materialId" = EXCLUDED."materialId", "studyBlockId" = EXCLUDED."studyBlockId", "question" = EXCLUDED."question", "answer" = EXCLUDED."answer", "type" = EXCLUDED."type", "difficulty" = EXCLUDED."difficulty", "status" = EXCLUDED."status", "reviewState" = EXCLUDED."reviewState", "learningStep" = EXCLUDED."learningStep", "easeFactor" = EXCLUDED."easeFactor", "intervalDays" = EXCLUDED."intervalDays", "repetitionCount" = EXCLUDED."repetitionCount", "lapseCount" = EXCLUDED."lapseCount", "lastReviewedAt" = EXCLUDED."lastReviewedAt", "nextReviewAt" = EXCLUDED."nextReviewAt", "approvedAt" = EXCLUDED."approvedAt", "sourcePageStart" = EXCLUDED."sourcePageStart", "sourcePageEnd" = EXCLUDED."sourcePageEnd", "createdAt" = EXCLUDED."createdAt", "updatedAt" = EXCLUDED."updatedAt", "generationReason" = EXCLUDED."generationReason";
INSERT INTO "Flashcard" ("id", "userId", "subjectId", "contentId", "materialId", "studyBlockId", "question", "answer", "type", "difficulty", "status", "reviewState", "learningStep", "easeFactor", "intervalDays", "repetitionCount", "lapseCount", "lastReviewedAt", "nextReviewAt", "approvedAt", "sourcePageStart", "sourcePageEnd", "createdAt", "updatedAt", "generationReason") VALUES ('cmrif88vl000zjr04mjwpd89v', 'cmp8od0wz0000iybklaotfqbs', 'cmp9zspkj0059l204sz3mezxt', NULL, NULL, NULL, 'Qual a concepção doutrinária amplamente dominante quanto à natureza da ''jurisdição voluntária''?', 'Prevalece o entendimento de que é uma atividade de administração pública de interesses privados (inexiste lide/litígio entre as partes)[cite: 18].', 'QUESTION_ANSWER', 'MEDIUM', 'APPROVED', 'REVIEW', 0, 2.65, 13, 5, 0, '2026-07-23T22:45:44.481', '2026-08-05T00:00:00', '2026-07-12T23:25:03.319', NULL, NULL, '2026-07-12T23:25:03.326', '2026-07-23T22:45:44.482', NULL) ON CONFLICT ("id") DO UPDATE SET "userId" = EXCLUDED."userId", "subjectId" = EXCLUDED."subjectId", "contentId" = EXCLUDED."contentId", "materialId" = EXCLUDED."materialId", "studyBlockId" = EXCLUDED."studyBlockId", "question" = EXCLUDED."question", "answer" = EXCLUDED."answer", "type" = EXCLUDED."type", "difficulty" = EXCLUDED."difficulty", "status" = EXCLUDED."status", "reviewState" = EXCLUDED."reviewState", "learningStep" = EXCLUDED."learningStep", "easeFactor" = EXCLUDED."easeFactor", "intervalDays" = EXCLUDED."intervalDays", "repetitionCount" = EXCLUDED."repetitionCount", "lapseCount" = EXCLUDED."lapseCount", "lastReviewedAt" = EXCLUDED."lastReviewedAt", "nextReviewAt" = EXCLUDED."nextReviewAt", "approvedAt" = EXCLUDED."approvedAt", "sourcePageStart" = EXCLUDED."sourcePageStart", "sourcePageEnd" = EXCLUDED."sourcePageEnd", "createdAt" = EXCLUDED."createdAt", "updatedAt" = EXCLUDED."updatedAt", "generationReason" = EXCLUDED."generationReason";
