INSERT INTO "Flashcard" ("id", "userId", "subjectId", "contentId", "materialId", "studyBlockId", "question", "answer", "type", "difficulty", "status", "reviewState", "learningStep", "easeFactor", "intervalDays", "repetitionCount", "lapseCount", "lastReviewedAt", "nextReviewAt", "approvedAt", "sourcePageStart", "sourcePageEnd", "createdAt", "updatedAt", "generationReason") VALUES ('cmrif88vj000hjr04tfb2wio3', 'cmp8od0wz0000iybklaotfqbs', 'cmp992nry0001l404o53vsbkj', NULL, NULL, NULL, 'Inexistindo cláusula expressa no contrato de trabalho a respeito das tarefas a serem executadas, a que tipo de serviço o empregado se obriga?', 'Entender-se-á que o empregado se obrigou a todo e qualquer serviço compatível com a sua condição pessoal (Art. 456, parágrafo único, da CLT).', 'QUESTION_ANSWER', 'MEDIUM', 'APPROVED', 'REVIEW', 0, 2.65, 13, 2, 0, '2026-07-16T14:09:20.813', '2026-07-29T00:00:00', '2026-07-12T23:25:03.317', NULL, NULL, '2026-07-12T23:25:03.326', '2026-07-16T14:09:20.814', NULL) ON CONFLICT ("id") DO UPDATE SET "userId" = EXCLUDED."userId", "subjectId" = EXCLUDED."subjectId", "contentId" = EXCLUDED."contentId", "materialId" = EXCLUDED."materialId", "studyBlockId" = EXCLUDED."studyBlockId", "question" = EXCLUDED."question", "answer" = EXCLUDED."answer", "type" = EXCLUDED."type", "difficulty" = EXCLUDED."difficulty", "status" = EXCLUDED."status", "reviewState" = EXCLUDED."reviewState", "learningStep" = EXCLUDED."learningStep", "easeFactor" = EXCLUDED."easeFactor", "intervalDays" = EXCLUDED."intervalDays", "repetitionCount" = EXCLUDED."repetitionCount", "lapseCount" = EXCLUDED."lapseCount", "lastReviewedAt" = EXCLUDED."lastReviewedAt", "nextReviewAt" = EXCLUDED."nextReviewAt", "approvedAt" = EXCLUDED."approvedAt", "sourcePageStart" = EXCLUDED."sourcePageStart", "sourcePageEnd" = EXCLUDED."sourcePageEnd", "createdAt" = EXCLUDED."createdAt", "updatedAt" = EXCLUDED."updatedAt", "generationReason" = EXCLUDED."generationReason";
INSERT INTO "Flashcard" ("id", "userId", "subjectId", "contentId", "materialId", "studyBlockId", "question", "answer", "type", "difficulty", "status", "reviewState", "learningStep", "easeFactor", "intervalDays", "repetitionCount", "lapseCount", "lastReviewedAt", "nextReviewAt", "approvedAt", "sourcePageStart", "sourcePageEnd", "createdAt", "updatedAt", "generationReason") VALUES ('cmrif88vj000njr04jirs7gbh', 'cmp8od0wz0000iybklaotfqbs', 'cmp992nry0001l404o53vsbkj', NULL, NULL, NULL, 'A empresa que se obriga, por norma regulamentar interna, a realizar inquérito ou sindicância antes de punir um empregado pode aplicar a sanção diretamente?', 'Não. Conforme a Súmula 77 do TST, é nula a punição do empregado se não precedida do inquérito ou sindicância internos a que a empresa se obrigou[cite: 14].', 'QUESTION_ANSWER', 'MEDIUM', 'APPROVED', 'REVIEW', 0, 2.65, 13, 2, 0, '2026-07-16T14:10:17.633', '2026-07-29T00:00:00', '2026-07-12T23:25:03.318', NULL, NULL, '2026-07-12T23:25:03.326', '2026-07-16T14:10:17.634', NULL) ON CONFLICT ("id") DO UPDATE SET "userId" = EXCLUDED."userId", "subjectId" = EXCLUDED."subjectId", "contentId" = EXCLUDED."contentId", "materialId" = EXCLUDED."materialId", "studyBlockId" = EXCLUDED."studyBlockId", "question" = EXCLUDED."question", "answer" = EXCLUDED."answer", "type" = EXCLUDED."type", "difficulty" = EXCLUDED."difficulty", "status" = EXCLUDED."status", "reviewState" = EXCLUDED."reviewState", "learningStep" = EXCLUDED."learningStep", "easeFactor" = EXCLUDED."easeFactor", "intervalDays" = EXCLUDED."intervalDays", "repetitionCount" = EXCLUDED."repetitionCount", "lapseCount" = EXCLUDED."lapseCount", "lastReviewedAt" = EXCLUDED."lastReviewedAt", "nextReviewAt" = EXCLUDED."nextReviewAt", "approvedAt" = EXCLUDED."approvedAt", "sourcePageStart" = EXCLUDED."sourcePageStart", "sourcePageEnd" = EXCLUDED."sourcePageEnd", "createdAt" = EXCLUDED."createdAt", "updatedAt" = EXCLUDED."updatedAt", "generationReason" = EXCLUDED."generationReason";
INSERT INTO "Flashcard" ("id", "userId", "subjectId", "contentId", "materialId", "studyBlockId", "question", "answer", "type", "difficulty", "status", "reviewState", "learningStep", "easeFactor", "intervalDays", "repetitionCount", "lapseCount", "lastReviewedAt", "nextReviewAt", "approvedAt", "sourcePageStart", "sourcePageEnd", "createdAt", "updatedAt", "generationReason") VALUES ('cmrif88vj000pjr04qjzgc799', 'cmp8od0wz0000iybklaotfqbs', 'cmp9zspkj0059l204sz3mezxt', NULL, NULL, NULL, 'O estímulo a métodos de solução consensual de conflitos (conciliação/mediação) cessa com o início da ação judicial?', 'Não. Conforme o art. 3º, § 3º, do CPC, o estímulo deve ocorrer inclusive no curso do processo judicial.', 'QUESTION_ANSWER', 'MEDIUM', 'APPROVED', 'REVIEW', 0, 2.65, 13, 2, 0, '2026-07-16T14:10:25.822', '2026-07-29T00:00:00', '2026-07-12T23:25:03.318', NULL, NULL, '2026-07-12T23:25:03.326', '2026-07-16T14:10:25.823', NULL) ON CONFLICT ("id") DO UPDATE SET "userId" = EXCLUDED."userId", "subjectId" = EXCLUDED."subjectId", "contentId" = EXCLUDED."contentId", "materialId" = EXCLUDED."materialId", "studyBlockId" = EXCLUDED."studyBlockId", "question" = EXCLUDED."question", "answer" = EXCLUDED."answer", "type" = EXCLUDED."type", "difficulty" = EXCLUDED."difficulty", "status" = EXCLUDED."status", "reviewState" = EXCLUDED."reviewState", "learningStep" = EXCLUDED."learningStep", "easeFactor" = EXCLUDED."easeFactor", "intervalDays" = EXCLUDED."intervalDays", "repetitionCount" = EXCLUDED."repetitionCount", "lapseCount" = EXCLUDED."lapseCount", "lastReviewedAt" = EXCLUDED."lastReviewedAt", "nextReviewAt" = EXCLUDED."nextReviewAt", "approvedAt" = EXCLUDED."approvedAt", "sourcePageStart" = EXCLUDED."sourcePageStart", "sourcePageEnd" = EXCLUDED."sourcePageEnd", "createdAt" = EXCLUDED."createdAt", "updatedAt" = EXCLUDED."updatedAt", "generationReason" = EXCLUDED."generationReason";
INSERT INTO "Flashcard" ("id", "userId", "subjectId", "contentId", "materialId", "studyBlockId", "question", "answer", "type", "difficulty", "status", "reviewState", "learningStep", "easeFactor", "intervalDays", "repetitionCount", "lapseCount", "lastReviewedAt", "nextReviewAt", "approvedAt", "sourcePageStart", "sourcePageEnd", "createdAt", "updatedAt", "generationReason") VALUES ('cmrif88vk000tjr04wnyo8nt4', 'cmp8od0wz0000iybklaotfqbs', 'cmp9zspkj0059l204sz3mezxt', NULL, NULL, NULL, 'Os magistrados e tribunais são obrigados a julgar os processos seguindo rigidamente a ordem cronológica de conclusão?', 'Não. O art. 12 do CPC estabelece que juízes e tribunais atenderão, PREFERENCIALMENTE, à ordem cronológica de conclusão.', 'QUESTION_ANSWER', 'MEDIUM', 'APPROVED', 'REVIEW', 0, 2.65, 13, 2, 0, '2026-07-16T14:10:51.802', '2026-07-29T00:00:00', '2026-07-12T23:25:03.319', NULL, NULL, '2026-07-12T23:25:03.326', '2026-07-16T14:10:51.804', NULL) ON CONFLICT ("id") DO UPDATE SET "userId" = EXCLUDED."userId", "subjectId" = EXCLUDED."subjectId", "contentId" = EXCLUDED."contentId", "materialId" = EXCLUDED."materialId", "studyBlockId" = EXCLUDED."studyBlockId", "question" = EXCLUDED."question", "answer" = EXCLUDED."answer", "type" = EXCLUDED."type", "difficulty" = EXCLUDED."difficulty", "status" = EXCLUDED."status", "reviewState" = EXCLUDED."reviewState", "learningStep" = EXCLUDED."learningStep", "easeFactor" = EXCLUDED."easeFactor", "intervalDays" = EXCLUDED."intervalDays", "repetitionCount" = EXCLUDED."repetitionCount", "lapseCount" = EXCLUDED."lapseCount", "lastReviewedAt" = EXCLUDED."lastReviewedAt", "nextReviewAt" = EXCLUDED."nextReviewAt", "approvedAt" = EXCLUDED."approvedAt", "sourcePageStart" = EXCLUDED."sourcePageStart", "sourcePageEnd" = EXCLUDED."sourcePageEnd", "createdAt" = EXCLUDED."createdAt", "updatedAt" = EXCLUDED."updatedAt", "generationReason" = EXCLUDED."generationReason";
INSERT INTO "Flashcard" ("id", "userId", "subjectId", "contentId", "materialId", "studyBlockId", "question", "answer", "type", "difficulty", "status", "reviewState", "learningStep", "easeFactor", "intervalDays", "repetitionCount", "lapseCount", "lastReviewedAt", "nextReviewAt", "approvedAt", "sourcePageStart", "sourcePageEnd", "createdAt", "updatedAt", "generationReason") VALUES ('cmrif88vk000vjr04bdhve6o8', 'cmp8od0wz0000iybklaotfqbs', 'cmp9zspkj0059l204sz3mezxt', NULL, NULL, NULL, 'É cabível o ajuizamento de ação meramente declaratória se já tiver ocorrido a efetiva violação do direito?', 'Sim. Conforme o art. 20 do CPC, é admissível a ação meramente declaratória, ainda que tenha ocorrido a violação do direito[cite: 16].', 'QUESTION_ANSWER', 'MEDIUM', 'APPROVED', 'REVIEW', 0, 2.65, 13, 2, 0, '2026-07-16T14:11:00.185', '2026-07-29T00:00:00', '2026-07-12T23:25:03.319', NULL, NULL, '2026-07-12T23:25:03.326', '2026-07-16T14:11:00.186', NULL) ON CONFLICT ("id") DO UPDATE SET "userId" = EXCLUDED."userId", "subjectId" = EXCLUDED."subjectId", "contentId" = EXCLUDED."contentId", "materialId" = EXCLUDED."materialId", "studyBlockId" = EXCLUDED."studyBlockId", "question" = EXCLUDED."question", "answer" = EXCLUDED."answer", "type" = EXCLUDED."type", "difficulty" = EXCLUDED."difficulty", "status" = EXCLUDED."status", "reviewState" = EXCLUDED."reviewState", "learningStep" = EXCLUDED."learningStep", "easeFactor" = EXCLUDED."easeFactor", "intervalDays" = EXCLUDED."intervalDays", "repetitionCount" = EXCLUDED."repetitionCount", "lapseCount" = EXCLUDED."lapseCount", "lastReviewedAt" = EXCLUDED."lastReviewedAt", "nextReviewAt" = EXCLUDED."nextReviewAt", "approvedAt" = EXCLUDED."approvedAt", "sourcePageStart" = EXCLUDED."sourcePageStart", "sourcePageEnd" = EXCLUDED."sourcePageEnd", "createdAt" = EXCLUDED."createdAt", "updatedAt" = EXCLUDED."updatedAt", "generationReason" = EXCLUDED."generationReason";
