INSERT INTO "Flashcard" ("id", "userId", "subjectId", "contentId", "materialId", "studyBlockId", "question", "answer", "type", "difficulty", "status", "reviewState", "learningStep", "easeFactor", "intervalDays", "repetitionCount", "lapseCount", "lastReviewedAt", "nextReviewAt", "approvedAt", "sourcePageStart", "sourcePageEnd", "createdAt", "updatedAt", "generationReason") VALUES ('cmr9sw5ba0001ld04j5ip0gyw', 'cmp8od0wz0000iybklaotfqbs', 'cmp992nry0001l404o53vsbkj', NULL, 'cmpe6yukz000jl504khl0ahu4', 'cmpe73v58004ql704iw27e6gb', 'Qual a distinção, como justa causa (CLT, art. 482, b), entre incontinência de conduta e mau procedimento?', 'Incontinência (moral sexual); Mau procedimento (outras dimensões da moral).', 'QUESTION_ANSWER', 'MEDIUM', 'APPROVED', 'REVIEW', 0, 2.95, 30, 6, 1, '2026-07-27T01:10:26.548', '2026-08-26T00:00:00', '2026-07-06T22:37:37.877', 3, 15, '2026-07-06T22:37:37.88', '2026-07-27T01:10:26.55', NULL) ON CONFLICT ("id") DO UPDATE SET "userId" = EXCLUDED."userId", "subjectId" = EXCLUDED."subjectId", "contentId" = EXCLUDED."contentId", "materialId" = EXCLUDED."materialId", "studyBlockId" = EXCLUDED."studyBlockId", "question" = EXCLUDED."question", "answer" = EXCLUDED."answer", "type" = EXCLUDED."type", "difficulty" = EXCLUDED."difficulty", "status" = EXCLUDED."status", "reviewState" = EXCLUDED."reviewState", "learningStep" = EXCLUDED."learningStep", "easeFactor" = EXCLUDED."easeFactor", "intervalDays" = EXCLUDED."intervalDays", "repetitionCount" = EXCLUDED."repetitionCount", "lapseCount" = EXCLUDED."lapseCount", "lastReviewedAt" = EXCLUDED."lastReviewedAt", "nextReviewAt" = EXCLUDED."nextReviewAt", "approvedAt" = EXCLUDED."approvedAt", "sourcePageStart" = EXCLUDED."sourcePageStart", "sourcePageEnd" = EXCLUDED."sourcePageEnd", "createdAt" = EXCLUDED."createdAt", "updatedAt" = EXCLUDED."updatedAt", "generationReason" = EXCLUDED."generationReason";
INSERT INTO "Flashcard" ("id", "userId", "subjectId", "contentId", "materialId", "studyBlockId", "question", "answer", "type", "difficulty", "status", "reviewState", "learningStep", "easeFactor", "intervalDays", "repetitionCount", "lapseCount", "lastReviewedAt", "nextReviewAt", "approvedAt", "sourcePageStart", "sourcePageEnd", "createdAt", "updatedAt", "generationReason") VALUES ('cmrii4cr1002fl6042vd7nmjv', 'cmp8od0wz0000iybklaotfqbs', 'cmp992nry0001l404o53vsbkj', NULL, NULL, NULL, 'Qual o valor da multa por litigância de má-fé e a alternativa para causas de valor irrisório ou inestimável?', 'A multa deve ser superior a 1% e inferior a 10% do valor corrigido da causa. Se o valor for irrisório ou inestimável, a multa pode ser fixada em até 10 vezes o valor do salário-mínimo (Art. 81, §2º, CPC)[cite: 28].', 'QUESTION_ANSWER', 'MEDIUM', 'APPROVED', 'REVIEW', 0, 2.65, 13, 5, 0, '2026-07-27T21:29:38.822', '2026-08-09T00:00:00', '2026-07-13T00:46:00.577', NULL, NULL, '2026-07-13T00:46:00.583', '2026-07-27T21:29:38.823', NULL) ON CONFLICT ("id") DO UPDATE SET "userId" = EXCLUDED."userId", "subjectId" = EXCLUDED."subjectId", "contentId" = EXCLUDED."contentId", "materialId" = EXCLUDED."materialId", "studyBlockId" = EXCLUDED."studyBlockId", "question" = EXCLUDED."question", "answer" = EXCLUDED."answer", "type" = EXCLUDED."type", "difficulty" = EXCLUDED."difficulty", "status" = EXCLUDED."status", "reviewState" = EXCLUDED."reviewState", "learningStep" = EXCLUDED."learningStep", "easeFactor" = EXCLUDED."easeFactor", "intervalDays" = EXCLUDED."intervalDays", "repetitionCount" = EXCLUDED."repetitionCount", "lapseCount" = EXCLUDED."lapseCount", "lastReviewedAt" = EXCLUDED."lastReviewedAt", "nextReviewAt" = EXCLUDED."nextReviewAt", "approvedAt" = EXCLUDED."approvedAt", "sourcePageStart" = EXCLUDED."sourcePageStart", "sourcePageEnd" = EXCLUDED."sourcePageEnd", "createdAt" = EXCLUDED."createdAt", "updatedAt" = EXCLUDED."updatedAt", "generationReason" = EXCLUDED."generationReason";
INSERT INTO "Flashcard" ("id", "userId", "subjectId", "contentId", "materialId", "studyBlockId", "question", "answer", "type", "difficulty", "status", "reviewState", "learningStep", "easeFactor", "intervalDays", "repetitionCount", "lapseCount", "lastReviewedAt", "nextReviewAt", "approvedAt", "sourcePageStart", "sourcePageEnd", "createdAt", "updatedAt", "generationReason") VALUES ('cmqu5yqai000djs04480jilst', 'cmp8od0wz0000iybklaotfqbs', 'cmp9zspkj0059l204sz3mezxt', NULL, 'cmpe6x9z70005l504gzwkl5im', 'cmpebcxfj002gkt042ap2b0j4', 'Qual a consequência para o réu que não regulariza a incapacidade processual na instância originária?', 'Ele será considerado revel no processo.', 'QUESTION_ANSWER', 'MEDIUM', 'APPROVED', 'REVIEW', 0, 2.95, 11, 8, 2, '2026-07-27T21:29:46.499', '2026-08-07T00:00:00', '2026-06-25T23:59:14.572', 5, 11, '2026-06-25T23:59:14.574', '2026-07-27T21:29:46.5', NULL) ON CONFLICT ("id") DO UPDATE SET "userId" = EXCLUDED."userId", "subjectId" = EXCLUDED."subjectId", "contentId" = EXCLUDED."contentId", "materialId" = EXCLUDED."materialId", "studyBlockId" = EXCLUDED."studyBlockId", "question" = EXCLUDED."question", "answer" = EXCLUDED."answer", "type" = EXCLUDED."type", "difficulty" = EXCLUDED."difficulty", "status" = EXCLUDED."status", "reviewState" = EXCLUDED."reviewState", "learningStep" = EXCLUDED."learningStep", "easeFactor" = EXCLUDED."easeFactor", "intervalDays" = EXCLUDED."intervalDays", "repetitionCount" = EXCLUDED."repetitionCount", "lapseCount" = EXCLUDED."lapseCount", "lastReviewedAt" = EXCLUDED."lastReviewedAt", "nextReviewAt" = EXCLUDED."nextReviewAt", "approvedAt" = EXCLUDED."approvedAt", "sourcePageStart" = EXCLUDED."sourcePageStart", "sourcePageEnd" = EXCLUDED."sourcePageEnd", "createdAt" = EXCLUDED."createdAt", "updatedAt" = EXCLUDED."updatedAt", "generationReason" = EXCLUDED."generationReason";
INSERT INTO "Flashcard" ("id", "userId", "subjectId", "contentId", "materialId", "studyBlockId", "question", "answer", "type", "difficulty", "status", "reviewState", "learningStep", "easeFactor", "intervalDays", "repetitionCount", "lapseCount", "lastReviewedAt", "nextReviewAt", "approvedAt", "sourcePageStart", "sourcePageEnd", "createdAt", "updatedAt", "generationReason") VALUES ('cmrii4cr0002dl604iq0iyfcd', 'cmp8od0wz0000iybklaotfqbs', 'cmpa1224d04ecl204k3bmfm7m', NULL, NULL, NULL, 'Por que está incorreta a tese de que o beneficiário da gratuidade da justiça não sofre condenação em custas ''exceto se for litigante de má-fé''?', 'Porque a condenação de sucumbência ocorre independentemente da má-fé; a diferença é que a gratuidade suspende a cobrança da sucumbência comum, mas NÃO suspende a obrigação de pagar as penalidades da litigância de má-fé (Art. 79 e Art. 98, §2º, CPC)[cite: 27].', 'QUESTION_ANSWER', 'MEDIUM', 'APPROVED', 'REVIEW', 0, 2.5, 15, 4, 0, '2026-07-27T21:32:31.382', '2026-08-11T00:00:00', '2026-07-13T00:46:00.577', NULL, NULL, '2026-07-13T00:46:00.583', '2026-07-27T21:32:31.384', NULL) ON CONFLICT ("id") DO UPDATE SET "userId" = EXCLUDED."userId", "subjectId" = EXCLUDED."subjectId", "contentId" = EXCLUDED."contentId", "materialId" = EXCLUDED."materialId", "studyBlockId" = EXCLUDED."studyBlockId", "question" = EXCLUDED."question", "answer" = EXCLUDED."answer", "type" = EXCLUDED."type", "difficulty" = EXCLUDED."difficulty", "status" = EXCLUDED."status", "reviewState" = EXCLUDED."reviewState", "learningStep" = EXCLUDED."learningStep", "easeFactor" = EXCLUDED."easeFactor", "intervalDays" = EXCLUDED."intervalDays", "repetitionCount" = EXCLUDED."repetitionCount", "lapseCount" = EXCLUDED."lapseCount", "lastReviewedAt" = EXCLUDED."lastReviewedAt", "nextReviewAt" = EXCLUDED."nextReviewAt", "approvedAt" = EXCLUDED."approvedAt", "sourcePageStart" = EXCLUDED."sourcePageStart", "sourcePageEnd" = EXCLUDED."sourcePageEnd", "createdAt" = EXCLUDED."createdAt", "updatedAt" = EXCLUDED."updatedAt", "generationReason" = EXCLUDED."generationReason";
INSERT INTO "Flashcard" ("id", "userId", "subjectId", "contentId", "materialId", "studyBlockId", "question", "answer", "type", "difficulty", "status", "reviewState", "learningStep", "easeFactor", "intervalDays", "repetitionCount", "lapseCount", "lastReviewedAt", "nextReviewAt", "approvedAt", "sourcePageStart", "sourcePageEnd", "createdAt", "updatedAt", "generationReason") VALUES ('cmrigv5hw0025l6044w0anf5i', 'cmp8od0wz0000iybklaotfqbs', 'cmp9zspkj0059l204sz3mezxt', NULL, NULL, NULL, 'A competência determinada em razão da matéria, da pessoa ou da função pode ser modificada ou derrogada por convenção das partes?', 'Não. Essas competências possuem natureza absoluta e são INDERROGÁVEIS por convenção das partes (Art. 62 do CPC)[cite: 26].', 'QUESTION_ANSWER', 'MEDIUM', 'APPROVED', 'REVIEW', 0, 2.5, 1, 5, 1, '2026-07-27T21:32:53.866', '2026-07-28T00:00:00', '2026-07-13T00:10:51.657', NULL, NULL, '2026-07-13T00:10:51.66', '2026-07-27T21:32:53.867', NULL) ON CONFLICT ("id") DO UPDATE SET "userId" = EXCLUDED."userId", "subjectId" = EXCLUDED."subjectId", "contentId" = EXCLUDED."contentId", "materialId" = EXCLUDED."materialId", "studyBlockId" = EXCLUDED."studyBlockId", "question" = EXCLUDED."question", "answer" = EXCLUDED."answer", "type" = EXCLUDED."type", "difficulty" = EXCLUDED."difficulty", "status" = EXCLUDED."status", "reviewState" = EXCLUDED."reviewState", "learningStep" = EXCLUDED."learningStep", "easeFactor" = EXCLUDED."easeFactor", "intervalDays" = EXCLUDED."intervalDays", "repetitionCount" = EXCLUDED."repetitionCount", "lapseCount" = EXCLUDED."lapseCount", "lastReviewedAt" = EXCLUDED."lastReviewedAt", "nextReviewAt" = EXCLUDED."nextReviewAt", "approvedAt" = EXCLUDED."approvedAt", "sourcePageStart" = EXCLUDED."sourcePageStart", "sourcePageEnd" = EXCLUDED."sourcePageEnd", "createdAt" = EXCLUDED."createdAt", "updatedAt" = EXCLUDED."updatedAt", "generationReason" = EXCLUDED."generationReason";
INSERT INTO "Flashcard" ("id", "userId", "subjectId", "contentId", "materialId", "studyBlockId", "question", "answer", "type", "difficulty", "status", "reviewState", "learningStep", "easeFactor", "intervalDays", "repetitionCount", "lapseCount", "lastReviewedAt", "nextReviewAt", "approvedAt", "sourcePageStart", "sourcePageEnd", "createdAt", "updatedAt", "generationReason") VALUES ('cmsdso9ki0009l404x9a03i4r', 'cmp8od0wz0000iybklaotfqbs', 'cmpa1224d04ecl204k3bmfm7m', NULL, 'cmpe6ymo1000hl504zzrp9ir8', 'cmpe75ba6006jl704ubj8i226', 'Quais as 4 exceções ao efeito da presunção de veracidade da revelia no processo do trabalho, conforme art. 844, §4º da CLT?', 'I - havendo pluralidade de reclamados, algum contestar; II - litígio sobre direitos indisponíveis; III - inicial sem instrumento indispensável à prova; IV - alegações inverossímeis ou contraditórias com prova dos autos.', 'QUESTION_ANSWER', 'MEDIUM', 'APPROVED', 'LEARNING', 1, 2.5, 0, 2, 0, '2026-08-03T22:47:44.378', '2026-08-03T22:57:44.377', '2026-08-03T22:22:17.194', 30, 37, '2026-08-03T22:22:17.197', '2026-08-03T22:47:44.379', NULL) ON CONFLICT ("id") DO UPDATE SET "userId" = EXCLUDED."userId", "subjectId" = EXCLUDED."subjectId", "contentId" = EXCLUDED."contentId", "materialId" = EXCLUDED."materialId", "studyBlockId" = EXCLUDED."studyBlockId", "question" = EXCLUDED."question", "answer" = EXCLUDED."answer", "type" = EXCLUDED."type", "difficulty" = EXCLUDED."difficulty", "status" = EXCLUDED."status", "reviewState" = EXCLUDED."reviewState", "learningStep" = EXCLUDED."learningStep", "easeFactor" = EXCLUDED."easeFactor", "intervalDays" = EXCLUDED."intervalDays", "repetitionCount" = EXCLUDED."repetitionCount", "lapseCount" = EXCLUDED."lapseCount", "lastReviewedAt" = EXCLUDED."lastReviewedAt", "nextReviewAt" = EXCLUDED."nextReviewAt", "approvedAt" = EXCLUDED."approvedAt", "sourcePageStart" = EXCLUDED."sourcePageStart", "sourcePageEnd" = EXCLUDED."sourcePageEnd", "createdAt" = EXCLUDED."createdAt", "updatedAt" = EXCLUDED."updatedAt", "generationReason" = EXCLUDED."generationReason";
INSERT INTO "Flashcard" ("id", "userId", "subjectId", "contentId", "materialId", "studyBlockId", "question", "answer", "type", "difficulty", "status", "reviewState", "learningStep", "easeFactor", "intervalDays", "repetitionCount", "lapseCount", "lastReviewedAt", "nextReviewAt", "approvedAt", "sourcePageStart", "sourcePageEnd", "createdAt", "updatedAt", "generationReason") VALUES ('cmrigv5hv001vl604nh9nt6xu', 'cmp8od0wz0000iybklaotfqbs', 'cmp9zspkj0059l204sz3mezxt', NULL, NULL, NULL, 'No caso de CONTINÊNCIA, se a ação continente tiver sido proposta ANTERIORMENTE, qual a consequência para o processo da ação contida?', 'No processo relativo à ação contida será proferida sentença SEM resolução de mérito (Art. 57 do CPC). A banca erra ao afirmar que a sentença seria ''com'' resolução.', 'QUESTION_ANSWER', 'MEDIUM', 'APPROVED', 'REVIEW', 0, 2.65, 13, 2, 0, '2026-07-22T22:46:47.27', '2026-08-04T00:00:00', '2026-07-13T00:10:51.656', NULL, NULL, '2026-07-13T00:10:51.66', '2026-07-22T22:46:47.271', NULL) ON CONFLICT ("id") DO UPDATE SET "userId" = EXCLUDED."userId", "subjectId" = EXCLUDED."subjectId", "contentId" = EXCLUDED."contentId", "materialId" = EXCLUDED."materialId", "studyBlockId" = EXCLUDED."studyBlockId", "question" = EXCLUDED."question", "answer" = EXCLUDED."answer", "type" = EXCLUDED."type", "difficulty" = EXCLUDED."difficulty", "status" = EXCLUDED."status", "reviewState" = EXCLUDED."reviewState", "learningStep" = EXCLUDED."learningStep", "easeFactor" = EXCLUDED."easeFactor", "intervalDays" = EXCLUDED."intervalDays", "repetitionCount" = EXCLUDED."repetitionCount", "lapseCount" = EXCLUDED."lapseCount", "lastReviewedAt" = EXCLUDED."lastReviewedAt", "nextReviewAt" = EXCLUDED."nextReviewAt", "approvedAt" = EXCLUDED."approvedAt", "sourcePageStart" = EXCLUDED."sourcePageStart", "sourcePageEnd" = EXCLUDED."sourcePageEnd", "createdAt" = EXCLUDED."createdAt", "updatedAt" = EXCLUDED."updatedAt", "generationReason" = EXCLUDED."generationReason";
INSERT INTO "Flashcard" ("id", "userId", "subjectId", "contentId", "materialId", "studyBlockId", "question", "answer", "type", "difficulty", "status", "reviewState", "learningStep", "easeFactor", "intervalDays", "repetitionCount", "lapseCount", "lastReviewedAt", "nextReviewAt", "approvedAt", "sourcePageStart", "sourcePageEnd", "createdAt", "updatedAt", "generationReason") VALUES ('cmrigv5hv001xl604nns8q21u', 'cmp8od0wz0000iybklaotfqbs', 'cmp9zspkj0059l204sz3mezxt', NULL, NULL, NULL, 'O que ocorre se a ação contida for proposta antes ou se as ações com relação de continência não correrem o risco de julgamento separado?', 'As ações serão necessariamente REUNIDAS para julgamento conjunto perante o juízo prevento (Art. 57, parte final, do CPC).', 'QUESTION_ANSWER', 'MEDIUM', 'APPROVED', 'REVIEW', 0, 2.65, 13, 2, 0, '2026-07-22T22:47:30.229', '2026-08-04T00:00:00', '2026-07-13T00:10:51.656', NULL, NULL, '2026-07-13T00:10:51.66', '2026-07-22T22:47:30.23', NULL) ON CONFLICT ("id") DO UPDATE SET "userId" = EXCLUDED."userId", "subjectId" = EXCLUDED."subjectId", "contentId" = EXCLUDED."contentId", "materialId" = EXCLUDED."materialId", "studyBlockId" = EXCLUDED."studyBlockId", "question" = EXCLUDED."question", "answer" = EXCLUDED."answer", "type" = EXCLUDED."type", "difficulty" = EXCLUDED."difficulty", "status" = EXCLUDED."status", "reviewState" = EXCLUDED."reviewState", "learningStep" = EXCLUDED."learningStep", "easeFactor" = EXCLUDED."easeFactor", "intervalDays" = EXCLUDED."intervalDays", "repetitionCount" = EXCLUDED."repetitionCount", "lapseCount" = EXCLUDED."lapseCount", "lastReviewedAt" = EXCLUDED."lastReviewedAt", "nextReviewAt" = EXCLUDED."nextReviewAt", "approvedAt" = EXCLUDED."approvedAt", "sourcePageStart" = EXCLUDED."sourcePageStart", "sourcePageEnd" = EXCLUDED."sourcePageEnd", "createdAt" = EXCLUDED."createdAt", "updatedAt" = EXCLUDED."updatedAt", "generationReason" = EXCLUDED."generationReason";
INSERT INTO "Flashcard" ("id", "userId", "subjectId", "contentId", "materialId", "studyBlockId", "question", "answer", "type", "difficulty", "status", "reviewState", "learningStep", "easeFactor", "intervalDays", "repetitionCount", "lapseCount", "lastReviewedAt", "nextReviewAt", "approvedAt", "sourcePageStart", "sourcePageEnd", "createdAt", "updatedAt", "generationReason") VALUES ('cmrigv5hv001zl6041sha6cmh', 'cmp8od0wz0000iybklaotfqbs', 'cmp9zspkj0059l204sz3mezxt', NULL, NULL, NULL, 'Qualquer espécie de incompetência judicial prorroga-se caso o réu não a alegue em preliminar de contestação?', 'Não. Apenas a incompetência RELATIVA prorroga-se (Art. 65 do CPC). A incompetência absoluta é fundada em ordem pública e pode ser declarada de ofício a qualquer tempo.', 'QUESTION_ANSWER', 'MEDIUM', 'APPROVED', 'REVIEW', 0, 2.65, 13, 2, 0, '2026-07-22T22:47:54.529', '2026-08-04T00:00:00', '2026-07-13T00:10:51.656', NULL, NULL, '2026-07-13T00:10:51.66', '2026-07-22T22:47:54.53', NULL) ON CONFLICT ("id") DO UPDATE SET "userId" = EXCLUDED."userId", "subjectId" = EXCLUDED."subjectId", "contentId" = EXCLUDED."contentId", "materialId" = EXCLUDED."materialId", "studyBlockId" = EXCLUDED."studyBlockId", "question" = EXCLUDED."question", "answer" = EXCLUDED."answer", "type" = EXCLUDED."type", "difficulty" = EXCLUDED."difficulty", "status" = EXCLUDED."status", "reviewState" = EXCLUDED."reviewState", "learningStep" = EXCLUDED."learningStep", "easeFactor" = EXCLUDED."easeFactor", "intervalDays" = EXCLUDED."intervalDays", "repetitionCount" = EXCLUDED."repetitionCount", "lapseCount" = EXCLUDED."lapseCount", "lastReviewedAt" = EXCLUDED."lastReviewedAt", "nextReviewAt" = EXCLUDED."nextReviewAt", "approvedAt" = EXCLUDED."approvedAt", "sourcePageStart" = EXCLUDED."sourcePageStart", "sourcePageEnd" = EXCLUDED."sourcePageEnd", "createdAt" = EXCLUDED."createdAt", "updatedAt" = EXCLUDED."updatedAt", "generationReason" = EXCLUDED."generationReason";
INSERT INTO "Flashcard" ("id", "userId", "subjectId", "contentId", "materialId", "studyBlockId", "question", "answer", "type", "difficulty", "status", "reviewState", "learningStep", "easeFactor", "intervalDays", "repetitionCount", "lapseCount", "lastReviewedAt", "nextReviewAt", "approvedAt", "sourcePageStart", "sourcePageEnd", "createdAt", "updatedAt", "generationReason") VALUES ('cmrigv5hw0027l6048529fkvv', 'cmp8od0wz0000iybklaotfqbs', 'cmp9zspkj0059l204sz3mezxt', NULL, NULL, NULL, 'A posterior mudança de domicílio do executado desloca a competência de uma execução fiscal já proposta?', 'Não. Conforme a Súmula 58 do STJ, proposta a execução fiscal, a posterior mudança de domicílio do executado não desloca a competência já fixada[cite: 26].', 'QUESTION_ANSWER', 'MEDIUM', 'APPROVED', 'REVIEW', 0, 2.65, 13, 2, 0, '2026-07-22T22:48:02.667', '2026-08-04T00:00:00', '2026-07-13T00:10:51.657', NULL, NULL, '2026-07-13T00:10:51.66', '2026-07-22T22:48:02.668', NULL) ON CONFLICT ("id") DO UPDATE SET "userId" = EXCLUDED."userId", "subjectId" = EXCLUDED."subjectId", "contentId" = EXCLUDED."contentId", "materialId" = EXCLUDED."materialId", "studyBlockId" = EXCLUDED."studyBlockId", "question" = EXCLUDED."question", "answer" = EXCLUDED."answer", "type" = EXCLUDED."type", "difficulty" = EXCLUDED."difficulty", "status" = EXCLUDED."status", "reviewState" = EXCLUDED."reviewState", "learningStep" = EXCLUDED."learningStep", "easeFactor" = EXCLUDED."easeFactor", "intervalDays" = EXCLUDED."intervalDays", "repetitionCount" = EXCLUDED."repetitionCount", "lapseCount" = EXCLUDED."lapseCount", "lastReviewedAt" = EXCLUDED."lastReviewedAt", "nextReviewAt" = EXCLUDED."nextReviewAt", "approvedAt" = EXCLUDED."approvedAt", "sourcePageStart" = EXCLUDED."sourcePageStart", "sourcePageEnd" = EXCLUDED."sourcePageEnd", "createdAt" = EXCLUDED."createdAt", "updatedAt" = EXCLUDED."updatedAt", "generationReason" = EXCLUDED."generationReason";
INSERT INTO "Flashcard" ("id", "userId", "subjectId", "contentId", "materialId", "studyBlockId", "question", "answer", "type", "difficulty", "status", "reviewState", "learningStep", "easeFactor", "intervalDays", "repetitionCount", "lapseCount", "lastReviewedAt", "nextReviewAt", "approvedAt", "sourcePageStart", "sourcePageEnd", "createdAt", "updatedAt", "generationReason") VALUES ('cmrigv5hw0029l6049w1znzyj', 'cmp8od0wz0000iybklaotfqbs', 'cmp9zspkj0059l204sz3mezxt', NULL, NULL, NULL, 'Processos com pedidos e causas de pedir diversos, mas que versem sobre o mesmo bem, podem ser reunidos para julgamento conjunto mesmo sem conexão?', 'Sim. O Art. 55, § 3º, do CPC determina a reunião de processos para julgamento conjunto caso haja risco de decisões conflitantes ou contraditórias, SALVO se um deles já houver sido sentenciado[cite: 27].', 'QUESTION_ANSWER', 'MEDIUM', 'APPROVED', 'REVIEW', 0, 2.65, 13, 2, 0, '2026-07-22T22:48:20.674', '2026-08-04T00:00:00', '2026-07-13T00:10:51.657', NULL, NULL, '2026-07-13T00:10:51.66', '2026-07-22T22:48:20.675', NULL) ON CONFLICT ("id") DO UPDATE SET "userId" = EXCLUDED."userId", "subjectId" = EXCLUDED."subjectId", "contentId" = EXCLUDED."contentId", "materialId" = EXCLUDED."materialId", "studyBlockId" = EXCLUDED."studyBlockId", "question" = EXCLUDED."question", "answer" = EXCLUDED."answer", "type" = EXCLUDED."type", "difficulty" = EXCLUDED."difficulty", "status" = EXCLUDED."status", "reviewState" = EXCLUDED."reviewState", "learningStep" = EXCLUDED."learningStep", "easeFactor" = EXCLUDED."easeFactor", "intervalDays" = EXCLUDED."intervalDays", "repetitionCount" = EXCLUDED."repetitionCount", "lapseCount" = EXCLUDED."lapseCount", "lastReviewedAt" = EXCLUDED."lastReviewedAt", "nextReviewAt" = EXCLUDED."nextReviewAt", "approvedAt" = EXCLUDED."approvedAt", "sourcePageStart" = EXCLUDED."sourcePageStart", "sourcePageEnd" = EXCLUDED."sourcePageEnd", "createdAt" = EXCLUDED."createdAt", "updatedAt" = EXCLUDED."updatedAt", "generationReason" = EXCLUDED."generationReason";
INSERT INTO "Flashcard" ("id", "userId", "subjectId", "contentId", "materialId", "studyBlockId", "question", "answer", "type", "difficulty", "status", "reviewState", "learningStep", "easeFactor", "intervalDays", "repetitionCount", "lapseCount", "lastReviewedAt", "nextReviewAt", "approvedAt", "sourcePageStart", "sourcePageEnd", "createdAt", "updatedAt", "generationReason") VALUES ('cmrii4cr1002hl6040ujdoygf', 'cmp8od0wz0000iybklaotfqbs', 'cmp992nry0001l404o53vsbkj', NULL, NULL, NULL, 'Como a FCC costuma tentar confundir o candidato nas alternativas sobre o teto da multa de litigância de má-fé em causas irrisórias?', 'A banca joga nas alternativas erradas que o limite seria de ''até 100 vezes o salário-mínimo'' ou que a multa ''não poderá ser superior a 1%''. O texto da lei diz nitidamente ''superior a 1%'' e limite de ''até 10 vezes'' o salário-mínimo[cite: 28].', 'QUESTION_ANSWER', 'MEDIUM', 'APPROVED', 'REVIEW', 0, 2.65, 13, 2, 0, '2026-07-22T22:48:46.545', '2026-08-04T00:00:00', '2026-07-13T00:46:00.578', NULL, NULL, '2026-07-13T00:46:00.583', '2026-07-22T22:48:46.546', NULL) ON CONFLICT ("id") DO UPDATE SET "userId" = EXCLUDED."userId", "subjectId" = EXCLUDED."subjectId", "contentId" = EXCLUDED."contentId", "materialId" = EXCLUDED."materialId", "studyBlockId" = EXCLUDED."studyBlockId", "question" = EXCLUDED."question", "answer" = EXCLUDED."answer", "type" = EXCLUDED."type", "difficulty" = EXCLUDED."difficulty", "status" = EXCLUDED."status", "reviewState" = EXCLUDED."reviewState", "learningStep" = EXCLUDED."learningStep", "easeFactor" = EXCLUDED."easeFactor", "intervalDays" = EXCLUDED."intervalDays", "repetitionCount" = EXCLUDED."repetitionCount", "lapseCount" = EXCLUDED."lapseCount", "lastReviewedAt" = EXCLUDED."lastReviewedAt", "nextReviewAt" = EXCLUDED."nextReviewAt", "approvedAt" = EXCLUDED."approvedAt", "sourcePageStart" = EXCLUDED."sourcePageStart", "sourcePageEnd" = EXCLUDED."sourcePageEnd", "createdAt" = EXCLUDED."createdAt", "updatedAt" = EXCLUDED."updatedAt", "generationReason" = EXCLUDED."generationReason";
INSERT INTO "Flashcard" ("id", "userId", "subjectId", "contentId", "materialId", "studyBlockId", "question", "answer", "type", "difficulty", "status", "reviewState", "learningStep", "easeFactor", "intervalDays", "repetitionCount", "lapseCount", "lastReviewedAt", "nextReviewAt", "approvedAt", "sourcePageStart", "sourcePageEnd", "createdAt", "updatedAt", "generationReason") VALUES ('cmrigv5hv0021l604bgvzy9xs', 'cmp8od0wz0000iybklaotfqbs', 'cmp9zspkj0059l204sz3mezxt', NULL, NULL, NULL, 'Caso a alegação de incompetência ABSOLUTA seja acolhida em juízo, o processo será extinto sem resolução do mérito?', 'Não. Tanto na incompetência absoluta quanto na relativa, o acolhimento acarreta a REMESSA dos autos ao juízo competente (Art. 64, § 3º, do CPC).', 'QUESTION_ANSWER', 'MEDIUM', 'APPROVED', 'REVIEW', 0, 2.65, 13, 3, 0, '2026-07-22T22:49:08.089', '2026-08-04T00:00:00', '2026-07-13T00:10:51.656', NULL, NULL, '2026-07-13T00:10:51.66', '2026-07-22T22:49:08.09', NULL) ON CONFLICT ("id") DO UPDATE SET "userId" = EXCLUDED."userId", "subjectId" = EXCLUDED."subjectId", "contentId" = EXCLUDED."contentId", "materialId" = EXCLUDED."materialId", "studyBlockId" = EXCLUDED."studyBlockId", "question" = EXCLUDED."question", "answer" = EXCLUDED."answer", "type" = EXCLUDED."type", "difficulty" = EXCLUDED."difficulty", "status" = EXCLUDED."status", "reviewState" = EXCLUDED."reviewState", "learningStep" = EXCLUDED."learningStep", "easeFactor" = EXCLUDED."easeFactor", "intervalDays" = EXCLUDED."intervalDays", "repetitionCount" = EXCLUDED."repetitionCount", "lapseCount" = EXCLUDED."lapseCount", "lastReviewedAt" = EXCLUDED."lastReviewedAt", "nextReviewAt" = EXCLUDED."nextReviewAt", "approvedAt" = EXCLUDED."approvedAt", "sourcePageStart" = EXCLUDED."sourcePageStart", "sourcePageEnd" = EXCLUDED."sourcePageEnd", "createdAt" = EXCLUDED."createdAt", "updatedAt" = EXCLUDED."updatedAt", "generationReason" = EXCLUDED."generationReason";
INSERT INTO "Flashcard" ("id", "userId", "subjectId", "contentId", "materialId", "studyBlockId", "question", "answer", "type", "difficulty", "status", "reviewState", "learningStep", "easeFactor", "intervalDays", "repetitionCount", "lapseCount", "lastReviewedAt", "nextReviewAt", "approvedAt", "sourcePageStart", "sourcePageEnd", "createdAt", "updatedAt", "generationReason") VALUES ('cmrii4cr0002bl6046msydrqd', 'cmp8od0wz0000iybklaotfqbs', 'cmp9zspkj0059l204sz3mezxt', NULL, NULL, NULL, 'A concessão da gratuidade da justiça afasta a condenação do beneficiário vencido ao pagamento de custas e honorários de sucumbência?', 'Não. O beneficiário É CONDENADO normalmente na sentença. A gratuidade apenas coloca as obrigações sob condição suspensiva de exigibilidade por 5 anos (Art. 98, §§ 2º e 3º, CPC)[cite: 27].', 'QUESTION_ANSWER', 'MEDIUM', 'APPROVED', 'REVIEW', 0, 2.65, 13, 3, 0, '2026-07-22T22:50:19.937', '2026-08-04T00:00:00', '2026-07-13T00:46:00.577', NULL, NULL, '2026-07-13T00:46:00.583', '2026-07-22T22:50:19.938', NULL) ON CONFLICT ("id") DO UPDATE SET "userId" = EXCLUDED."userId", "subjectId" = EXCLUDED."subjectId", "contentId" = EXCLUDED."contentId", "materialId" = EXCLUDED."materialId", "studyBlockId" = EXCLUDED."studyBlockId", "question" = EXCLUDED."question", "answer" = EXCLUDED."answer", "type" = EXCLUDED."type", "difficulty" = EXCLUDED."difficulty", "status" = EXCLUDED."status", "reviewState" = EXCLUDED."reviewState", "learningStep" = EXCLUDED."learningStep", "easeFactor" = EXCLUDED."easeFactor", "intervalDays" = EXCLUDED."intervalDays", "repetitionCount" = EXCLUDED."repetitionCount", "lapseCount" = EXCLUDED."lapseCount", "lastReviewedAt" = EXCLUDED."lastReviewedAt", "nextReviewAt" = EXCLUDED."nextReviewAt", "approvedAt" = EXCLUDED."approvedAt", "sourcePageStart" = EXCLUDED."sourcePageStart", "sourcePageEnd" = EXCLUDED."sourcePageEnd", "createdAt" = EXCLUDED."createdAt", "updatedAt" = EXCLUDED."updatedAt", "generationReason" = EXCLUDED."generationReason";
INSERT INTO "Flashcard" ("id", "userId", "subjectId", "contentId", "materialId", "studyBlockId", "question", "answer", "type", "difficulty", "status", "reviewState", "learningStep", "easeFactor", "intervalDays", "repetitionCount", "lapseCount", "lastReviewedAt", "nextReviewAt", "approvedAt", "sourcePageStart", "sourcePageEnd", "createdAt", "updatedAt", "generationReason") VALUES ('cmrif88vi0001jr04ge3v21so', 'cmp8od0wz0000iybklaotfqbs', 'cmqzwtycf0001jo04lalmmuv3', NULL, NULL, NULL, 'Como são classificadas as normas constitucionais que criam órgãos ou estabelecem as opções políticas de organização do Estado e dos Poderes?', 'Normas de princípio institutivo ou organizativo (ex: art. 18, §2º, que trata de Territórios Federais)[cite: 6].', 'QUESTION_ANSWER', 'MEDIUM', 'APPROVED', 'REVIEW', 0, 2.65, 13, 5, 0, '2026-07-23T22:47:27.846', '2026-08-05T00:00:00', '2026-07-12T23:25:03.308', NULL, NULL, '2026-07-12T23:25:03.326', '2026-07-23T22:47:27.847', NULL) ON CONFLICT ("id") DO UPDATE SET "userId" = EXCLUDED."userId", "subjectId" = EXCLUDED."subjectId", "contentId" = EXCLUDED."contentId", "materialId" = EXCLUDED."materialId", "studyBlockId" = EXCLUDED."studyBlockId", "question" = EXCLUDED."question", "answer" = EXCLUDED."answer", "type" = EXCLUDED."type", "difficulty" = EXCLUDED."difficulty", "status" = EXCLUDED."status", "reviewState" = EXCLUDED."reviewState", "learningStep" = EXCLUDED."learningStep", "easeFactor" = EXCLUDED."easeFactor", "intervalDays" = EXCLUDED."intervalDays", "repetitionCount" = EXCLUDED."repetitionCount", "lapseCount" = EXCLUDED."lapseCount", "lastReviewedAt" = EXCLUDED."lastReviewedAt", "nextReviewAt" = EXCLUDED."nextReviewAt", "approvedAt" = EXCLUDED."approvedAt", "sourcePageStart" = EXCLUDED."sourcePageStart", "sourcePageEnd" = EXCLUDED."sourcePageEnd", "createdAt" = EXCLUDED."createdAt", "updatedAt" = EXCLUDED."updatedAt", "generationReason" = EXCLUDED."generationReason";
