INSERT INTO "Flashcard" ("id", "userId", "subjectId", "contentId", "materialId", "studyBlockId", "question", "answer", "type", "difficulty", "status", "reviewState", "learningStep", "easeFactor", "intervalDays", "repetitionCount", "lapseCount", "lastReviewedAt", "nextReviewAt", "approvedAt", "sourcePageStart", "sourcePageEnd", "createdAt", "updatedAt", "generationReason") VALUES ('cmrii4cr1002ll604esnuqmvd', 'cmp8od0wz0000iybklaotfqbs', 'cmpa1224d04ecl204k3bmfm7m', NULL, NULL, NULL, 'Na organização da Justiça do Trabalho, onde são propostas as ações caso a comarca local não possua uma Vara do Trabalho instituída?', 'A lei poderá atribuir essa jurisdição aos Juízes de Direito (Justiça Comum Estadual), com recurso para o respectivo TRT (Art. 112, CF). A banca erra ao afirmar que a ação iria para a ''Vara do Trabalho mais próxima''[cite: 29].', 'QUESTION_ANSWER', 'MEDIUM', 'APPROVED', 'REVIEW', 0, 2.65, 13, 2, 0, '2026-07-22T22:53:22.611', '2026-08-04T00:00:00', '2026-07-13T00:46:00.578', NULL, NULL, '2026-07-13T00:46:00.583', '2026-07-22T22:53:22.612', NULL) ON CONFLICT ("id") DO UPDATE SET "userId" = EXCLUDED."userId", "subjectId" = EXCLUDED."subjectId", "contentId" = EXCLUDED."contentId", "materialId" = EXCLUDED."materialId", "studyBlockId" = EXCLUDED."studyBlockId", "question" = EXCLUDED."question", "answer" = EXCLUDED."answer", "type" = EXCLUDED."type", "difficulty" = EXCLUDED."difficulty", "status" = EXCLUDED."status", "reviewState" = EXCLUDED."reviewState", "learningStep" = EXCLUDED."learningStep", "easeFactor" = EXCLUDED."easeFactor", "intervalDays" = EXCLUDED."intervalDays", "repetitionCount" = EXCLUDED."repetitionCount", "lapseCount" = EXCLUDED."lapseCount", "lastReviewedAt" = EXCLUDED."lastReviewedAt", "nextReviewAt" = EXCLUDED."nextReviewAt", "approvedAt" = EXCLUDED."approvedAt", "sourcePageStart" = EXCLUDED."sourcePageStart", "sourcePageEnd" = EXCLUDED."sourcePageEnd", "createdAt" = EXCLUDED."createdAt", "updatedAt" = EXCLUDED."updatedAt", "generationReaso