INSERT INTO "Flashcard" ("id", "userId", "subjectId", "contentId", "materialId", "studyBlockId", "question", "answer", "type", "difficulty", "status", "reviewState", "learningStep", "easeFactor", "intervalDays", "repetitionCount", "lapseCount", "lastReviewedAt", "nextReviewAt", "approvedAt", "sourcePageStart", "sourcePageEnd", "createdAt", "updatedAt", "generationReason") VALUES ('cmrii4cr2002tl604jkl5pszp', 'cmp8od0wz0000iybklaotfqbs', 'cmp992nry0001l404o53vsbkj', NULL, NULL, NULL, 'Como o examinador tenta afastar o candidato da resposta correta sobre a designação do distribuidor na CLT?', 'A banca cria subordinações absurdas nas alternativas erradas, afirmando que os funcionários estariam subordinados ao ''Presidente do TST'', ao ''Juiz mais antigo da comarca'' ou ao ''Diretor do Fórum''.', 'QUESTION_ANSWER', 'MEDIUM', 'APPROVED', 'REVIEW', 0, 2.65, 13, 2, 0, '2026-07-22T22:53:44.051', '2026-08-04T00:00:00', '2026-07-13T00:46:00.579', NULL, NULL, '2026-07-13T00:46:00.583', '2026-07-22T22:53:44.052', NULL) ON CONFLICT ("id") DO UPDATE SET "userId" = EXCLUDED."userId", "subjectId" = EXCLUDED."subjectId", "contentId" = EXCLUDED."contentId", "materialId" = EXCLUDED."materialId", "studyBlockId" = EXCLUDED."studyBlockId", "question" = EXCLUDED."question", "answer" = EXCLUDED."answer", "type" = EXCLUDED."type", "difficulty" = EXCLUDED."difficulty", "status" = EXCLUDED."status", "reviewState" = EXCLUDED."reviewState", "learningStep" = EXCLUDED."learningStep", "easeFactor" = EXCLUDED."easeFactor", "intervalDays" = EXCLUDED."intervalDays", "repetitionCount" = EXCLUDED."repetitionCount", "lapseCount" = EXCLUDED."lapseCount", "lastReviewedAt" = EXCLUDED."lastReviewedAt", "nextReviewAt" = EXCLUDED."nextReviewAt", "approvedAt" = EXCLUDED."approvedAt", "sourcePageStart" = EXCLUDED."sourcePageStart", "sourcePageEnd" = EXCLUDED."sourcePageEnd", "createdAt" = EXCLUDED."createdAt", "updatedAt" = EXCLUDED."updatedAt", "generationReason" = EXCLUDED."generationReason";
INSERT INTO "Flashcard" ("id", "userId", "subjectId", "contentId", "materialId", "studyBlockId", "question", "answer", "type", "difficulty", "status", "reviewState", "learningStep", "easeFactor", "intervalDays", "repetitionCount", "lapseCount", "lastReviewedAt", "nextReviewAt", "approvedAt", "sourcePageStart", "sourcePageEnd", "createdAt", "updatedAt", "generationReason") VALUES ('cmrii4cr30031l604oi1c9fku', 'cmp8od0wz0000iybklaotfqbs', 'cmqzwtycf0001jo04lalmmuv3', NULL, NULL, NULL, 'Nos juízos divisórios, não havendo litígio, e nos casos de transação sem disposição sobre despesas, como é feito o pagamento?', 'Nos juízos divisórios vigora a proporção dos quinhões (Art. 89). Na transação omissa, as despesas são divididas igualmente por meio de rateio por igual (Art. 90, §2º). A banca erra ao dizer que na transação o réu pagaria tudo[cite: 32].', 'QUESTION_ANSWER', 'MEDIUM', 'APPROVED', 'REVIEW', 0, 2.65, 13, 2, 0, '2026-07-22T22:55:09.041', '2026-08-04T00:00:00', '2026-07-13T00:46:00.58', NULL, NULL, '2026-07-13T00:46:00.583', '2026-07-22T22:55:09.042', NULL) ON CONFLICT ("id") DO UPDATE SET "userId" = EXCLUDED."userId", "subjectId" = EXCLUDED."subjectId", "contentId" = EXCLUDED."contentId", "materialId" = EXCLUDED."materialId", "studyBlockId" = EXCLUDED."studyBlockId", "question" = EXCLUDED."question", "answer" = EXCLUDED."answer", "type" = EXCLUDED."type", "difficulty" = EXCLUDED."difficulty", "status" = EXCLUDED."status", "reviewState" = EXCLUDED."reviewState", "learningStep" = EXCLUDED."learningStep", "easeFactor" = EXCLUDED."easeFactor", "intervalDays" = EXCLUDED."intervalDays", "repetitionCount" = EXCLUDED."repetitionCount", "lapseCount" = EXCLUDED."lapseCount", "lastReviewedAt" = EXCLUDED."lastReviewedAt", "nextReviewAt" = EXCLUDED."nextReviewAt", "approvedAt" = EXCLUDED."approvedAt", "sourcePageStart" = EXCLUDED."sourcePageStart", "sourcePageEnd" = EXCLUDED."sourcePageEnd", "createdAt" = EXCLUDED."createdAt", "updatedAt" = EXCLUDED."updatedAt", "generationReason" = EXCLUDED."generationReason";
INSERT INTO "Flashcard" ("id", "userId", "subjectId", "contentId", "materialId", "studyBlockId", "question", "answer", "type", "difficulty", "status", "reviewState", "learningStep", "easeFactor", "intervalDays", "repetitionCount", "lapseCount", "lastReviewedAt", "nextReviewAt", "approvedAt", "sourcePageStart", "sourcePageEnd", "createdAt", "updatedAt", "generationReason") VALUES ('cmrii4cr30033l6043pa4i9i4', 'cmp8od0wz0000iybklaotfqbs', 'cmp9zspkj0059l204sz3mezxt', NULL, NULL, NULL, 'Os honorários advocatícios sucumbenciais podem ser compensados entre os advogados em caso de sucumbência parcial?', 'Não. Os honorários possuem natureza alimentar, constituindo direito autônomo do advogado, sendo expressamente vedada a sua compensação (Art. 85, § 14, do CPC).', 'QUESTION_ANSWER', 'MEDIUM', 'APPROVED', 'REVIEW', 0, 2.65, 13, 2, 0, '2026-07-22T22:55:21.392', '2026-08-04T00:00:00', '2026-07-13T00:46:00.58', NULL, NULL, '2026-07-13T00:46:00.583', '2026-07-22T22:55:21.393', NULL) ON CONFLICT ("id") DO UPDATE SET "userId" = EXCLUDED."userId", "subjectId" = EXCLUDED."subjectId", "contentId" = EXCLUDED."contentId", "materialId" = EXCLUDED."materialId", "studyBlockId" = EXCLUDED."studyBlockId", "question" = EXCLUDED."question", "answer" = EXCLUDED."answer", "type" = EXCLUDED."type", "difficulty" = EXCLUDED."difficulty", "status" = EXCLUDED."status", "reviewState" = EXCLUDED."reviewState", "learningStep" = EXCLUDED."learningStep", "easeFactor" = EXCLUDED."easeFactor", "intervalDays" = EXCLUDED."intervalDays", "repetitionCount" = EXCLUDED."repetitionCount", "lapseCount" = EXCLUDED."lapseCount", "lastReviewedAt" = EXCLUDED."lastReviewedAt", "nextReviewAt" = EXCLUDED."nextReviewAt", "approvedAt" = EXCLUDED."approvedAt", "sourcePageStart" = EXCLUDED."sourcePageStart", "sourcePageEnd" = EXCLUDED."sourcePageEnd", "createdAt" = EXCLUDED."createdAt", "updatedAt" = EXCLUDED."updatedAt", "generationReason" = EXCLUDED."generationReason";
INSERT INTO "Flashcard" ("id", "userId", "subjectId", "contentId", "materialId", "studyBlockId", "question", "answer", "type", "difficulty", "status", "reviewState", "learningStep", "easeFactor", "intervalDays", "repetitionCount", "lapseCount", "lastReviewedAt", "nextReviewAt", "approvedAt", "sourcePageStart", "sourcePageEnd", "createdAt", "updatedAt", "generationReason") VALUES ('cmrii4cr2002zl604i3oafuou', 'cmp8od0wz0000iybklaotfqbs', 'cmp9zspkj0059l204sz3mezxt', NULL, NULL, NULL, 'Se um litigante decair ou sucumbir em PARTE MÍNIMA do pedido, as despesas e honorários serão distribuídos reciprocamente entre as partes?', 'Não. Se a sucumbência for mínima, a outra parte responderá POR INTEIRO pelas despesas e pelos honorários (Art. 86, parágrafo único, do CPC). A banca tenta forçar o rateio proporcional.', 'QUESTION_ANSWER', 'MEDIUM', 'APPROVED', 'REVIEW', 0, 2.65, 13, 3, 0, '2026-07-22T22:55:42.873', '2026-08-04T00:00:00', '2026-07-13T00:46:00.58', NULL, NULL, '2026-07-13T00:46:00.583', '2026-07-22T22:55:42.874', NULL) ON CONFLICT ("id") DO UPDATE SET "userId" = EXCLUDED."userId", "subjectId" = EXCLUDED."subjectId", "contentId" = EXCLUDED."contentId", "materialId" = EXCLUDED."materialId", "studyBlockId" = EXCLUDED."studyBlockId", "question" = EXCLUDED."question", "answer" = EXCLUDED."answer", "type" = EXCLUDED."type", "difficulty" = EXCLUDED."difficulty", "status" = EXCLUDED."status", "reviewState" = EXCLUDED."reviewState", "learningStep" = EXCLUDED."learningStep", "easeFactor" = EXCLUDED."easeFactor", "intervalDays" = EXCLUDED."intervalDays", "repetitionCount" = EXCLUDED."repetitionCount", "lapseCount" = EXCLUDED."lapseCount", "lastReviewedAt" = EXCLUDED."lastReviewedAt", "nextReviewAt" = EXCLUDED."nextReviewAt", "approvedAt" = EXCLUDED."approvedAt", "sourcePageStart" = EXCLUDED."sourcePageStart", "sourcePageEnd" = EXCLUDED."sourcePageEnd", "createdAt" = EXCLUDED."createdAt", "updatedAt" = EXCLUDED."updatedAt", "generationReason" = EXCLUDED."generationReason";
INSERT INTO "Flashcard" ("id", "userId", "subjectId", "contentId", "materialId", "studyBlockId", "question", "answer", "type", "difficulty", "status", "reviewState", "learningStep", "easeFactor", "intervalDays", "repetitionCount", "lapseCount", "lastReviewedAt", "nextReviewAt", "approvedAt", "sourcePageStart", "sourcePageEnd", "createdAt", "updatedAt", "generationReason") VALUES ('cmrii4cr30035l604k20dcc6c', 'cmp8od0wz0000iybklaotfqbs', 'cmp9zspkj0059l204sz3mezxt', NULL, NULL, NULL, 'A partir de qual momento contam-se os juros moratórios quando os honorários advocatícios forem fixados em quantia certa?', 'Incidirão obrigatoriamente a partir da data do TRÂNSTO EM JULGADO da decisão (Art. 85, § 16, do CPC). A banca coloca ''a partir da citação'' para induzir ao erro civil comum.', 'QUESTION_ANSWER', 'MEDIUM', 'APPROVED', 'REVIEW', 0, 2.65, 13, 3, 0, '2026-07-22T22:55:59.429', '2026-08-04T00:00:00', '2026-07-13T00:46:00.58', NULL, NULL, '2026-07-13T00:46:00.583', '2026-07-22T22:55:59.43', NULL) ON CONFLICT ("id") DO UPDATE SET "userId" = EXCLUDED."userId", "subjectId" = EXCLUDED."subjectId", "contentId" = EXCLUDED."contentId", "materialId" = EXCLUDED."materialId", "studyBlockId" = EXCLUDED."studyBlockId", "question" = EXCLUDED."question", "answer" = EXCLUDED."answer", "type" = EXCLUDED."type", "difficulty" = EXCLUDED."difficulty", "status" = EXCLUDED."status", "reviewState" = EXCLUDED."reviewState", "learningStep" = EXCLUDED."learningStep", "easeFactor" = EXCLUDED."easeFactor", "intervalDays" = EXCLUDED."intervalDays", "repetitionCount" = EXCLUDED."repetitionCount", "lapseCount" = EXCLUDED."lapseCount", "lastReviewedAt" = EXCLUDED."lastReviewedAt", "nextReviewAt" = EXCLUDED."nextReviewAt", "approvedAt" = EXCLUDED."approvedAt", "sourcePageStart" = EXCLUDED."sourcePageStart", "sourcePageEnd" = EXCLUDED."sourcePageEnd", "createdAt" = EXCLUDED."createdAt", "updatedAt" = EXCLUDED."updatedAt", "generationReason" = EXCLUDED."generationReason";
INSERT INTO "Flashcard" ("id", "userId", "subjectId", "contentId", "materialId", "studyBlockId", "question", "answer", "type", "difficulty", "status", "reviewState", "learningStep", "easeFactor", "intervalDays", "repetitionCount", "lapseCount", "lastReviewedAt", "nextReviewAt", "approvedAt", "sourcePageStart", "sourcePageEnd", "createdAt", "updatedAt", "generationReason") VALUES ('cmrii4cr2002pl604dts8g00k', 'cmp8od0wz0000iybklaotfqbs', 'cmpa1224d04ecl204k3bmfm7m', NULL, NULL, NULL, 'Qual a composição mínima de juízes de um TRT e por quem eles são nomeados?', 'Composto por, no mínimo, 7 juízes, nomeados pelo Presidente da República (Art. 115, CF). A banca tenta enganar afirmando que seriam no mínimo 9 juízes ou nomeados pelo Presidente do TST[cite: 29].', 'QUESTION_ANSWER', 'MEDIUM', 'APPROVED', 'REVIEW', 0, 2.65, 13, 4, 0, '2026-07-23T22:48:22.493', '2026-08-05T00:00:00', '2026-07-13T00:46:00.578', NULL, NULL, '2026-07-13T00:46:00.583', '2026-07-23T22:48:22.494', NULL) ON CONFLICT ("id") DO UPDATE SET "userId" = EXCLUDED."userId", "subjectId" = EXCLUDED."subjectId", "contentId" = EXCLUDED."contentId", "materialId" = EXCLUDED."materialId", "studyBlockId" = EXCLUDED."studyBlockId", "question" = EXCLUDED."question", "answer" = EXCLUDED."answer", "type" = EXCLUDED."type", "difficulty" = EXCLUDED."difficulty", "status" = EXCLUDED."status", "reviewState" = EXCLUDED."reviewState", "learningStep" = EXCLUDED."learningStep", "easeFactor" = EXCLUDED."easeFactor", "intervalDays" = EXCLUDED."intervalDays", "repetitionCount" = EXCLUDED."repetitionCount", "lapseCount" = EXCLUDED."lapseCount", "lastReviewedAt" = EXCLUDED."lastReviewedAt", "nextReviewAt" = EXCLUDED."nextReviewAt", "approvedAt" = EXCLUDED."approvedAt", "sourcePageStart" = EXCLUDED."sourcePageStart", "sourcePageEnd" = EXCLUDED."sourcePageEnd", "createdAt" = EXCLUDED."createdAt", "updatedAt" = EXCLUDED."updatedAt", "generationReason" = EXCLUDED."generationReason";
INSERT INTO "Flashcard" ("id", "userId", "subjectId", "contentId", "materialId", "studyBlockId", "question", "answer", "type", "difficulty", "status", "reviewState", "learningStep", "easeFactor", "intervalDays", "repetitionCount", "lapseCount", "lastReviewedAt", "nextReviewAt", "approvedAt", "sourcePageStart", "sourcePageEnd", "createdAt", "updatedAt", "generationReason") VALUES ('cmrii4cr2002rl604mr99u2ib', 'cmp8od0wz0000iybklaotfqbs', 'cmp992nry0001l404o53vsbkj', NULL, NULL, NULL, 'A quem compete, nos termos da CLT, realizar a designação dos funcionários que atuarão no órgão auxiliar de Distribuição das Varadas do Trabalho?', 'Compete ao Presidente do Tribunal Regional do Trabalho (TRT), dentre funcionários das Varas e do Tribunal existentes na mesma localidade (Art. 715 da CLT).', 'QUESTION_ANSWER', 'MEDIUM', 'APPROVED', 'REVIEW', 0, 2.65, 13, 4, 0, '2026-07-23T22:48:40.263', '2026-08-05T00:00:00', '2026-07-13T00:46:00.579', NULL, NULL, '2026-07-13T00:46:00.583', '2026-07-23T22:48:40.264', NULL) ON CONFLICT ("id") DO UPDATE SET "userId" = EXCLUDED."userId", "subjectId" = EXCLUDED."subjectId", "contentId" = EXCLUDED."contentId", "materialId" = EXCLUDED."materialId", "studyBlockId" = EXCLUDED."studyBlockId", "question" = EXCLUDED."question", "answer" = EXCLUDED."answer", "type" = EXCLUDED."type", "difficulty" = EXCLUDED."difficulty", "status" = EXCLUDED."status", "reviewState" = EXCLUDED."reviewState", "learningStep" = EXCLUDED."learningStep", "easeFactor" = EXCLUDED."easeFactor", "intervalDays" = EXCLUDED."intervalDays", "repetitionCount" = EXCLUDED."repetitionCount", "lapseCount" = EXCLUDED."lapseCount", "lastReviewedAt" = EXCLUDED."lastReviewedAt", "nextReviewAt" = EXCLUDED."nextReviewAt", "approvedAt" = EXCLUDED."approvedAt", "sourcePageStart" = EXCLUDED."sourcePageStart", "sourcePageEnd" = EXCLUDED."sourcePageEnd", "createdAt" = EXCLUDED."createdAt", "updatedAt" = EXCLUDED."updatedAt", "generationReason" = EXCLUDED."generationReason";
