INSERT INTO "Flashcard" ("id", "userId", "subjectId", "contentId", "materialId", "studyBlockId", "question", "answer", "type", "difficulty", "status", "reviewState", "learningStep", "easeFactor", "intervalDays", "repetitionCount", "lapseCount", "lastReviewedAt", "nextReviewAt", "approvedAt", "sourcePageStart", "sourcePageEnd", "createdAt", "updatedAt", "generationReason") VALUES ('cmppzlvpt000ble04af2nkehq', 'cmp8od0wz0000iybklaotfqbs', 'cmpa1224d04ecl204k3bmfm7m', NULL, 'cmpd3swqc001nlh04kszowfx7', 'cmpd43mr800b1la04251codx2', 'Qual o tipo de litisconsórcio que pode ser fracionado pelo juiz ou a requerimento do réu e qual o efeito do requerimento de limitação?', 'O litisconsórcio facultativo (multitudinário). O requerimento de limitação interrompe o prazo para manifestação ou resposta (Art. 113, §2º CPC).', 'QUESTION_ANSWER', 'MEDIUM', 'APPROVED', 'REVIEW', 0, 3.1, 15, 8, 1, '2026-07-20T23:18:54.999', '2026-08-04T00:00:00', '2026-05-28T21:10:30.341', 25, 35, '2026-05-28T21:10:30.344', '2026-07-20T23:18:55', NULL) ON CONFLICT ("id") DO UPDATE SET "userId" = EXCLUDED."userId", "subjectId" = EXCLUDED."subjectId", "contentId" = EXCLUDED."contentId", "materialId" = EXCLUDED."materialId", "studyBlockId" = EXCLUDED."studyBlockId", "question" = EXCLUDED."question", "answer" = EXCLUDED."answer", "type" = EXCLUDED."type", "difficulty" = EXCLUDED."difficulty", "status" = EXCLUDED."status", "reviewState" = EXCLUDED."reviewState", "learningStep" = EXCLUDED."learningStep", "easeFactor" = EXCLUDED."easeFactor", "intervalDays" = EXCLUDED."intervalDays", "repetitionCount" = EXCLUDED."repetitionCount", "lapseCount" = EXCLUDED."lapseCount", "lastReviewedAt" = EXCLUDED."lastReviewedAt", "nextReviewAt" = EXCLUDED."nextReviewAt", "approvedAt" = EXCLUDED."approvedAt", "sourcePageStart" = EXCLUDED."sourcePageStart", "sourcePageEnd" = EXCLUDED."sourcePageEnd", "createdAt" = EXCLUDED."createdAt", "updatedAt" = EXCLUDED."updatedAt", "generationReason" = EXCLUDED."generationReason";
INSERT INTO "Flashcard" ("id", "userId", "subjectId", "contentId", "materialId", "studyBlockId", "question", "answer", "type", "difficulty", "status", "reviewState", "learningStep", "easeFactor", "intervalDays", "repetitionCount", "lapseCount", "lastReviewedAt", "nextReviewAt", "approvedAt", "sourcePageStart", "sourcePageEnd", "createdAt", "updatedAt", "generationReason") VALUES ('cmrigv5hu001rl604seo9z2y3', 'cmp8od0wz0000iybklaotfqbs', 'cmp9zspkj0059l204sz3mezxt', NULL, NULL, NULL, 'Se a União intervir em processo de RECUPERAÇÃO JUDICIAL ou FALÊNCIA na Justiça Comum, os autos devem ser remetidos à Justiça Federal?', 'Não. As ações de recuperação judicial, falência, insolvência civil e acidente de trabalho são EXCEÇÕES expressas e permanecem na Justiça Comum (Art. 45, I, do CPC e Art. 109, I, da CF)[cite: 25].', 'QUESTION_ANSWER', 'MEDIUM', 'APPROVED', 'REVIEW', 0, 2.65, 13, 2, 0, '2026-07-20T23:19:17.782', '2026-08-02T00:00:00', '2026-07-13T00:10:51.655', NULL, NULL, '2026-07-13T00:10:51.66', '2026-07-20T23:19:17.783', NULL) ON CONFLICT ("id") DO UPDATE SET "userId" = EXCLUDED."userId", "subjectId" = EXCLUDED."subjectId", "contentId" = EXCLUDED."contentId", "materialId" = EXCLUDED."materialId", "studyBlockId" = EXCLUDED."studyBlockId", "question" = EXCLUDED."question", "answer" = EXCLUDED."answer", "type" = EXCLUDED."type", "difficulty" = EXCLUDED."difficulty", "status" = EXCLUDED."status", "reviewState" = EXCLUDED."reviewState", "learningStep" = EXCLUDED."learningStep", "easeFactor" = EXCLUDED."easeFactor", "intervalDays" = EXCLUDED."intervalDays", "repetitionCount" = EXCLUDED."repetitionCount", "lapseCount" = EXCLUDED."lapseCount", "lastReviewedAt" = EXCLUDED."lastReviewedAt", "nextReviewAt" = EXCLUDED."nextReviewAt", "approvedAt" = EXCLUDED."approvedAt", "sourcePageStart" = EXCLUDED."sourcePageStart", "sourcePageEnd" = EXCLUDED."sourcePageEnd", "createdAt" = EXCLUDED."createdAt", "updatedAt" = EXCLUDED."updatedAt", "generationReason" = EXCLUDED."generationReason";
